Upstream Context:
{
  "Queen": {
    "projectGoal": "To provide users with an intuitive tool for tracking fitness activities, managing exercises, reviewing workout history, and gaining insights through data visualization.",
    "constraints": [
      "Single-user application scope",
      "Basic data persistence using local storage or simple file-based storage",
      "No external API integrations",
