                    </div>
                  </div>
                  <p className="text-gray-600 text-sm mt-1">{exercise.description}</p>
                  <div className="mt-2 flex flex-wrap gap-2">
                    <span className="text-xs bg-purple-100 text-purple-800 px-2 py-1 rounded">{exercise.category}</span>
                    {exercise.sets && <span className="text-xs bg-yellow-100 text-yellow-800 px-2 py-1 rounded">{exercise.sets} sets</span>}
                    {exercise.reps && <span className="text-xs bg-yellow-100 text-yellow-800 px-2 py-1 rounded">{exercise.reps} reps</span>}
                    {exercise.weight && <span className="text-xs bg-yellow-100 text-yellow-800 px-2 py-1 rounded">{exercise.weight} kg</span>}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      );
    }

    // Render the app
    ReactDOM.render(<App />, document.getElementById('root'));
  </script>
</body>
</html>",
    "src/app.js": "import { createWorkout } from './api/workout-api.js';
import { getWorkouts } from './api/workout-api.js';
import { createExercise } from './api/exercise-api.js';
import { updateExercise } from './api/exercise-api.js';
import { deleteExercise } from './api/exercise-api.js';
import { getExercises } from './api/exercise-api.js';

// Main application class to orchestrate modules
export class WorkoutApp {
  constructor() {
    this.workouts = [];
    this.exercises = [];
  }

  async initialize() {
    try {
      // Load initial data
      await this.loadWorkouts();
      await this.loadExercises();
      console.log('Application initialized successfully');
    } catch (error) {
      console.error('Failed to initialize application:', error);
      throw error;
    }
  }

  async loadWorkouts() {
    try {
      this.workouts = await getWorkouts();
      console.log('Workouts loaded:', this.workouts.length);
    } catch (error) {
      console.error('Failed to load workouts:', error);
      throw error;
    }
  }

  async loadExercises() {
    try {
      this.exercises = await getExercises();
      console.log('Exercises loaded:', this.exercises.length);
    } catch (error) {
      console.error('Failed to load exercises:', error);
      throw error;
    }
  }

  async createWorkout(workoutData) {
    try {
      const newWorkout = await createWorkout(workoutData);
      this.workouts.push(newWorkout);
      return newWorkout;
    } catch (error) {
      console.error('Failed to create workout:', error);
      throw error;
    }
  }

  async createExercise(exerciseData) {
    try {
      const newExercise = await createExercise(exerciseData);
      this.exercises.push(newExercise);
      return newExercise;
    } catch (error) {
      console.error('Failed to create exercise:', error);
      throw error;
    }
  }

  async updateExercise(id, exerciseData) {
    try {
      const updatedExercise = await updateExercise(id, exerciseData);
      // Update in local array
      const index = this.exercises.findIndex(ex => ex.id === id);
      if (index !== -1) {
        this.exercises[index] = updatedExercise;
      }
      return updatedExercise;
    } catch (error) {
      console.error('Failed to update exercise:', error);
      throw error;
    }
  }

  async deleteExercise(id) {
    try {
      await deleteExercise(id);
      // Remove from local array
      this.exercises = this.exercises.filter(ex => ex.id !== id);
      console.log(`Exercise ${id} deleted`);
    } catch (error) {
      console.error('Failed to delete exercise:', error);
      throw error;
    }
  }

  getWorkouts() {
    return this.workouts;
  }

  getExercises() {
    return this.exercises;
  }

  getWorkoutById(id) {
    return this.workouts.find(workout => workout.id === id);
  }

  getExerciseById(id) {
    return this.exercises.find(exercise => exercise.id === id);
  }
}

// Export singleton instance
export const app = new WorkoutApp();",
    "src/modules/workoutRecorder.js": "/*
 * Handles creation and saving of new workouts
 */

// API endpoint for creating workouts
const CREATE_WORKOUT_API = 'api-create-workout';

/**
 * Creates a new workout object with the provided details
 * @param {Object} workoutData - The data for the new workout
 * @param {string} workoutData.name - Name of the workout
 * @param {string} workoutData.description - Description of the workout
 * @param {Array} workoutData.exercises - Array of exercise objects
 * @param {string} workoutData.date - Date of the workout
 * @returns {Object} The created workout object
 */
export function createWorkout(workoutData) {
  // Validate required fields
  if (!workoutData.name || !workoutData.date) {
    throw new Error('Workout name and date are required');
  }

  // Create the workout object with default values
  const workout = {
    id: generateWorkoutId(),
    name: workoutData.name,
    description: workoutData.description || '',
    exercises: workoutData.exercises || [],
    date: workoutData.date,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  };

  return workout;
}

/**
 * Saves a workout to the backend
 * @param {Object} workout - The workout object to save
 * @returns {Promise<Object>} The saved workout object
 */
export async function saveWorkout(workout) {
  try {
    // Validate workout object
    if (!workout || !workout.id) {
      throw new Error('Invalid workout object');
    }

    // Update the updatedAt timestamp
    workout.updatedAt = new Date().toISOString();

    // Make API call to save workout
    const response = await fetch(CREATE_WORKOUT_API, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(workout)
    });

    if (!response.ok) {
      throw new Error(`Failed to save workout: ${response.status}`);
    }

    const savedWorkout = await response.json();
    return savedWorkout;
  } catch (error) {
    console.error('Error saving workout:', error);
    throw error;
  }
}

/**
 * Generates a unique ID for a workout
 * @returns {string} A unique workout ID
 */
function generateWorkoutId() {
  // Simple UUID-like ID generation
  return 'workout-' + Date.now() + '-' + Math.random().toString(36).substr(2, 9);
}

/**
 * Adds an exercise to a workout
 * @param {Object} workout - The workout object
 * @param {Object} exercise - The exercise to add
 * @returns {Object} The updated workout object
 */
export function addExerciseToWorkout(workout, exercise) {
  if (!workout.exercises) {
    workout.exercises = [];
  }

  workout.exercises.push({
    id: generateExerciseId(),
    ...exercise,
    createdAt: new Date().toISOString()
  });

  return workout;
}

/**
 * Generates a unique ID for an exercise
 * @returns {string} A unique exercise ID
 */
function generateExerciseId() {
  // Simple UUID-like ID generation
  return 'exercise-' + Date.now() + '-' + Math.random().toString(36).substr(2, 9);
}

/**
 * Removes an exercise from a workout
 * @param {Object} workout - The workout object
 * @param {string} exerciseId - The ID of the exercise to remove
 * @returns {Object} The updated workout object
 */
export function removeExerciseFromWorkout(workout, exerciseId) {
  if (workout.exercises) {
    workout.exercises = workout.exercises.filter(exercise => exercise.id !== exerciseId);
  }

  return workout;
}

/**
 * Updates a workout in the backend
 * @param {Object} workout - The workout object to update
 * @returns {Promise<Object>} The updated workout object
 */
export async function updateWorkout(workout) {
  try {
    // Validate workout object
    if (!workout || !workout.id) {
      throw new Error('Invalid workout object');
    }

    // Update the updatedAt timestamp
    workout.updatedAt = new Date().toISOString();

    // Make API call to update workout
    const response = await fetch(`${CREATE_WORKOUT_API}/${workout.id}`, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(workout)
    });

