export const processWorkoutData = (workouts) => {
  if (!workouts || !Array.isArray(workouts)) {
    return [];
  }

  // Process workouts for chart rendering
  const chartData = workouts.map(workout => ({
    date: new Date(workout.date).toLocaleDateString(),
    duration: workout.duration,
    calories: workout.calories,
    type: workout.type
  }));

  // Process workouts for history display
  const historyData = workouts.map(workout => ({
    id: workout.id,
    date: new Date(workout.date).toLocaleDateString(),
    duration: workout.duration,
    calories: workout.calories,
    type: workout.type,
    notes: workout.notes || ''
  }));

  return {
    chartData,
    historyData
  };
};

export const getWorkoutSummary = (workouts) => {
  if (!workouts || !Array.isArray(workouts)) {
    return {
      totalWorkouts: 0,
      totalDuration: 0,
      totalCalories: 0,
      averageDuration: 0
    };
  }

  const totalWorkouts = workouts.length;
  const totalDuration = workouts.reduce((sum, workout) => sum + workout.duration, 0);
  const totalCalories = workouts.reduce((sum, workout) => sum + workout.calories, 0);
  const averageDuration = totalWorkouts > 0 ? Math.round(totalDuration / totalWorkouts) : 0;

  return {
    totalWorkouts,
    totalDuration,
    totalCalories,
    averageDuration
  };
};

