Upstream Context:
{
  "Queen": {
    "projectGoal": "To provide users with an intuitive tool for tracking fitness activities, managing exercises, reviewing workout history, and gaining insights through data visualization.",
    "constraints": [
      "Single-user application scope",
      "Basic data persistence using local storage or simple file-based storage",
      "No external API integrations",
      "Minimal UI/UX requirements for MVP",
      "No real-time collaboration features"
    ]
  },
  "Security": null,
  "Coder": {
    "src/utils/storageManager.js": "class StorageManager {
  constructor() {
    this.workoutsKey = 'workouts';
    this.exercisesKey = 'exercises';
  }

  // Workout operations
  createWorkout(workout) {
    const workouts = this.getWorkouts();
    const newWorkout = {
      ...workout,
      id: Date.now().toString(),
      createdAt: new Date().toISOString()
    };
    workouts.push(newWorkout);
    this.setWorkouts(workouts);
    return newWorkout;
  }

  getWorkouts() {
    const workouts = localStorage.getItem(this.workoutsKey);
    return workouts ? JSON.parse(workouts) : [];
  }

  updateWorkout(id, updates) {
    const workouts = this.getWorkouts();
    const index = workouts.findIndex(w => w.id === id);
    if (index !== -1) {
      workouts[index] = { ...workouts[index], ...updates };
      this.setWorkouts(workouts);
      return workouts[index];
    }
    return null;
  }

  deleteWorkout(id) {
    const workouts = this.getWorkouts();
    const filteredWorkouts = workouts.filter(w => w.id !== id);
    this.setWorkouts(filteredWorkouts);
    return filteredWorkouts;
  }

  // Exercise operations
  createExercise(exercise) {
    const exercises = this.getExercises();
    const newExercise = {
      ...exercise,
      id: Date.now().toString(),
      createdAt: new Date().toISOString()
    };
    exercises.push(newExercise);
    this.setExercises(exercises);
    return newExercise;
  }

  getExercises() {
    const exercises = localStorage.getItem(this.exercisesKey);
    return exercises ? JSON.parse(exercises) : [];
  }

  updateExercise(id, updates) {
    const exercises = this.getExercises();
    const index = exercises.findIndex(e => e.id === id);
    if (index !== -1) {
      exercises[index] = { ...exercises[index], ...updates };
      this.setExercises(exercises);
      return exercises[index];
    }
    return null;
  }

  deleteExercise(id) {
    const exercises = this.getExercises();
    const filteredExercises = exercises.filter(e => e.id !== id);
    this.setExercises(filteredExercises);
    return filteredExercises;
  }

  // Private methods
  setWorkouts(workouts) {
    localStorage.setItem(this.workoutsKey, JSON.stringify(workouts));
  }

  setExercises(exercises) {
    localStorage.setItem(this.exercisesKey, JSON.stringify(exercises));
  }
}

// Export singleton instance
const storageManager = new StorageManager();
export default storageManager;",
    "src/utils/dataProcessor.js": "export const processWorkoutData = (workouts) => {
  if (!workouts || !Array.isArray(workouts)) {
    return [];
  }

  // Process workouts for chart rendering
  const chartData = workouts.map(workout => ({
    date: new Date(workout.date).toLocaleDateString(),
    duration: workout.duration,
    calories: workout.calories,
    type: workout.type
  }));

  // Process workouts for history display
  const historyData = workouts.map(workout => ({
    id: workout.id,
    date: new Date(workout.date).toLocaleDateString(),
    duration: workout.duration,
    calories: workout.calories,
    type: workout.type,
    notes: workout.notes || ''
  }));

  return {
    chartData,
    historyData
  };
};

export const getWorkoutSummary = (workouts) => {
  if (!workouts || !Array.isArray(workouts)) {
    return {
      totalWorkouts: 0,
      totalDuration: 0,
      totalCalories: 0,
      averageDuration: 0
    };
  }

  const totalWorkouts = workouts.length;
  const totalDuration = workouts.reduce((sum, workout) => sum + workout.duration, 0);
  const totalCalories = workouts.reduce((sum, workout) => sum + workout.calories, 0);
  const averageDuration = totalWorkouts > 0 ? Math.round(totalDuration / totalWorkouts) : 0;

  return {
    totalWorkouts,
    totalDuration,
    totalCalories,
    averageDuration
  };
};",
    "src/components/workoutForm.js": "import React, { useState } from 'react';

const WorkoutForm = () => {
  const [workoutData, setWorkoutData] = useState({
    name: '',
    type: '',
    duration: '',
    calories: '',
    date: ''
  });

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitSuccess, setSubmitSuccess] = useState(false);
  const [submitError, setSubmitError] = useState('');

  const handleChange = (e) => {
    const { name, value } = e.target;
    setWorkoutData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);
    setSubmitError('');
    setSubmitSuccess(false);

    try {
      const response = await fetch('/api-create-workout', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(workoutData)
      });

      if (!response.ok) {
        throw new Error(`Error: ${response.status}`);
      }

      setSubmitSuccess(true);
      // Reset form after successful submission
      setWorkoutData({
        name: '',
        type: '',
        duration: '',
        calories: '',
        date: ''
      });
    } catch (error) {
      setSubmitError(error.message);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="max-w-md mx-auto p-6 bg-white rounded-lg shadow-md">
      <h2 className="text-2xl font-bold text-gray-800 mb-4">Record New Workout</h2>

      {submitSuccess && (
        <div className="mb-4 p-3 bg-green-100 text-green-700 rounded">
          Workout recorded successfully!
        </div>
      )}

      {submitError && (
        <div className="mb-4 p-3 bg-red-100 text-red-700 rounded">
          {submitError}
        </div>
      )}

      <form onSubmit={handleSubmit} className="space-y-4">
        <div>
          <label htmlFor="name" className="block text-sm font-medium text-gray-700 mb-1">
            Workout Name
          </label>
          <input
            type="text"
            id="name"
            name="name"
            value={workoutData.name}
            onChange={handleChange}
            required
            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
            placeholder="e.g., Morning Run"
          />
        </div>

        <div>
          <label htmlFor="type" className="block text-sm font-medium text-gray-700 mb-1">
            Workout Type
          </label>
          <select
            id="type"
            name="type"
            value={workoutData.type}
            onChange={handleChange}
            required
            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
          >
            <option value="">Select a type</option>
            <option value="running">Running</option>
            <option value="cycling">Cycling</option>
            <option value="swimming">Swimming</option>
            <option value="weightlifting">Weight Lifting</option>
            <option value="yoga">Yoga</option>
            <option value="other">Other</option>
          </select>
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div>
            <label htmlFor="duration" className="block text-sm font-medium text-gray-700 mb-1">
              Duration (minutes)
            </label>
            <input
              type="number"
              id="duration"
              name="duration"
              value={workoutData.duration}
              onChange={handleChange}
              required
              min="1"
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
              placeholder="e.g., 30"
            />
          </div>

          <div>
            <label htmlFor="calories" className="block text-sm font-medium text-gray-700 mb-1">
              Calories Burned
            </label>
            <input
              type="number"
              id="calories"
              name="calories"
              value={workoutData.calories}
              onChange={handleChange}
              required
              min="1"
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
              placeholder="e.g., 300"
            />
          </div>
        </div>

        <div>
          <label htmlFor="date" className="block text-sm font-medium text-gray-700 mb-1">
            Date
          </label>
          <input
            type="date"
            id="date"
            name="date"
            value={workoutData.date}
            onChange={handleChange}
            required
            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
        </div>

        <button
          type="submit"
          disabled={isSubmitting}
          className={`w-full py-2 px-4 rounded-md text-white font-medium ${isSubmitting ? 'bg-gray-400' : 'bg-blue-600 hover:bg-blue-700'} transition-colors duration-200`}
        >
          {isSubmitting ? 'Recording...' : 'Record Workout'}
        </button>
      </form>
    </div>
  );
};

export default WorkoutForm;",
    "src/components/exerciseList.js": "import React, { useState, useEffect } from 'react';

const ExerciseList = () => {
  const [exercises, setExercises] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [newExercise, setNewExercise] = useState({
    name: '',
    description: '',
    category: '',
    difficulty: 'beginner'
  });
  const [editingId, setEditingId] = useState(null);
  const [editForm, setEditForm] = useState({
    name: '',
    description: '',
    category: '',
    difficulty: 'beginner'
  });

  // Fetch exercises on component mount
  useEffect(() => {
    fetchExercises();
  }, []);

  const fetchExercises = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/get-exercises');
      if (!response.ok) {
        throw new Error('Failed to fetch exercises');
      }
      const data = await response.json();
      setExercises(data);
      setError(null);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleCreateExercise = async (e) => {
    e.preventDefault();
    try {
      const response = await fetch('/api/create-exercise', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(newExercise),
      });

      if (!response.ok) {
        throw new Error('Failed to create exercise');
      }

      const createdExercise = await response.json();
      setExercises([...exercises, createdExercise]);
      setNewExercise({
        name: '',
        description: '',
        category: '',
        difficulty: 'beginner'
      });
    } catch (err) {
      setError(err.message);
    }
  };

  const handleUpdateExercise = async (e) => {
    e.preventDefault();
    try {
      const response = await fetch(`/api/update-exercise/${editingId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(editForm),
      });

      if (!response.ok) {
        throw new Error('Failed to update exercise');
      }

      const updatedExercise = await response.json();
      setExercises(exercises.map(ex => ex.id === editingId ? updatedExercise : ex));
      setEditingId(null);
      setEditForm({
        name: '',
        description: '',
        category: '',
        difficulty: 'beginner'
      });
    } catch (err) {
      setError(err.message);
    }
  };

  const handleDeleteExercise = async (id) => {
    try {
      const response = await fetch(`/api/delete-exercise/${id}`, {
        method: 'DELETE',
      });

      if (!response.ok) {
        throw new Error('Failed to delete exercise');
      }

      setExercises(exercises.filter(ex => ex.id !== id));
    } catch (err) {
      setError(err.message);
    }
  };

  const startEditing = (exercise) => {
    setEditingId(exercise.id);
    setEditForm({
      name: exercise.name,
      description: exercise.description,
      category: exercise.category,
      difficulty: exercise.difficulty
    });
  };

  const cancelEditing = () => {
    setEditingId(null);
    setEditForm({
      name: '',
      description: '',
      category: '',
      difficulty: 'beginner'
    });
  };

  if (loading) {
    return <div className="text-center py-8">Loading exercises...</div>;
  }

  if (error) {
    return (
      <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded relative" role="alert">
        <strong className="font-bold">Error! </strong>
        <span className="block sm:inline">{error}</span>
      </div>
    );
  }

  return (
    <div className="max-w-6xl mx-auto px-4 py-8">
