class ExerciseManager {
  constructor() {
    this.exercises = [];
    this.nextId = 1;
  }

  // API: api-create-exercise
  createExercise(exerciseData) {
    const exercise = {
      id: this.nextId++,
      ...exerciseData,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };

    this.exercises.push(exercise);
    return exercise;
  }

  // API: api-get-exercises
  getExercises() {
    return this.exercises;
  }

  // API: api-update-exercise
  updateExercise(id, exerciseData) {
    const index = this.exercises.findIndex(ex => ex.id === id);

    if (index === -1) {
      throw new Error('Exercise not found');
    }

    this.exercises[index] = {
      ...this.exercises[index],
      ...exerciseData,
      updatedAt: new Date().toISOString()
    };

    return this.exercises[index];
  }

  // API: api-delete-exercise
  deleteExercise(id) {
    const index = this.exercises.findIndex(ex => ex.id === id);

    if (index === -1) {
      throw new Error('Exercise not found');
    }

    return this.exercises.splice(index, 1)[0];
  }
}

// Export the ExerciseManager class
export default ExerciseManager;

