      chartContainer.id = chartId;
      chartContainer.style.width = '100%';
      chartContainer.style.height = '400px';
      document.body.appendChild(chartContainer);
    }

    // Prepare data for charting library
    const processedData = this.processWorkoutData(workoutData);

    // Generate chart based on type
    let chartInstance;
    switch (type.toLowerCase()) {
      case 'line':
        chartInstance = this.createLineChart(chartContainer, processedData, options);
        break;
      case 'bar':
        chartInstance = this.createBarChart(chartContainer, processedData, options);
        break;
      case 'pie':
        chartInstance = this.createPieChart(chartContainer, processedData, options);
        break;
      default:
        throw new Error(`Unsupported chart type: ${type}`);
