          legend: {
            display: true
          },
          title: {
            display: true,
            text: 'Workout Distribution'
          }
        }
      }
    };

    // Return chart instance (simplified for this implementation)
    return {
      type: 'pie',
      data,
      options,
      canvas
    };
  }

  /**
   * Updates an existing chart with new data
   * @param {string} chartId - Unique identifier for the chart
   * @param {Array} newData - New workout data to update chart with
   */
  updateChart(chartId, newData) {
    const chartInstance = this.chartInstances.get(chartId);
    if (!chartInstance) {
      throw new Error(`Chart with ID ${chartId} not found`);
    }

    // Process new data
    const processedData = this.processWorkoutData(newData);

    // Update chart instance (simplified)
    chartInstance.data = processedData;

    return chartInstance;
  }

  /**
   * Removes a chart from the DOM and cleans up references
   * @param {string} chartId - Unique identifier for the chart
   */
  removeChart(chartId) {
    const chartContainer = document.getElementById(chartId);
    if (chartContainer) {
      chartContainer.remove();
    }

    this.chartInstances.delete(chartId);
  }
}

// Export the ChartRenderer class
export default ChartRenderer;"
}

