    "src/components/chartComponent.js": "import React from 'react';

const ChartComponent = ({ data, type = 'bar', title = '' }) => {
  // Validate data
  if (!data || !Array.isArray(data) || data.length === 0) {
    return (
      <div className="p-4 bg-gray-50 rounded-lg border border-gray-200">
        <p className="text-gray-500 text-center">No data available for chart</p>
      </div>
    );
  }

  // Prepare chart configuration based on type
  const chartConfig = {
    bar: {
      chartType: 'bar',
      color: 'bg-blue-500',
      height: 'h-64',
    },
    line: {
      chartType: 'line',
      color: 'bg-green-500',
      height: 'h-64',
    },
    pie: {
      chartType: 'pie',
      color: 'bg-purple-500',
      height: 'h-64',
    },
  };

  const config = chartConfig[type] || chartConfig.bar;

  // Render bar chart
  if (config.chartType === 'bar') {
    const maxValue = Math.max(...data.map(item => item.value));

    return (
      <div className="p-6 bg-white rounded-lg shadow-md border border-gray-200">
        {title && <h3 className="text-lg font-semibold text-gray-800 mb-4">{title}</h3>}
        <div className="flex items-end justify-between h-64 space-x-2">
          {data.map((item, index) => (
            <div key={index} className="flex flex-col items-center flex-1">
              <div 
                className={`${config.color} rounded-t w-full transition-all duration-300 hover:opacity-75`}
                style={{ height: `${(item.value / maxValue) * 100}%` }}
              />
              <span className="mt-2 text-xs text-gray-600 text-center">{item.label}</span>
            </div>
          ))}
        </div>
      </div>
    );
  }

  // Render line chart
  if (config.chartType === 'line') {
    const maxValue = Math.max(...data.map(item => item.value));

    return (
      <div className="p-6 bg-white rounded-lg shadow-md border border-gray-200">
        {title && <h3 className="text-lg font-semibold text-gray-800 mb-4">{title}</h3>}
        <div className="relative h-64 w-full">
          <svg className="w-full h-full" viewBox="0 0 400 200">
            <polyline
              fill="none"
              stroke="#3B82F6"
              strokeWidth="2"
              points={data.map((item, index) => {
                const x = (index / (data.length - 1)) * 400;
                const y = 200 - (item.value / maxValue) * 180;
                return `${x},${y}`;
              }).join(' ')}
            />
            {data.map((item, index) => {
              const x = (index / (data.length - 1)) * 400;
              const y = 200 - (item.value / maxValue) * 180;
              return (
                <circle
                  key={index}
                  cx={x}
                  cy={y}
                  r="4"
                  fill="#3B82F6"
                />
              );
            })}
          </svg>
        </div>
      </div>
    );
  }

  // Render pie chart
  if (config.chartType === 'pie') {
    const total = data.reduce((sum, item) => sum + item.value, 0);
    let startAngle = 0;

    return (
      <div className="p-6 bg-white rounded-lg shadow-md border border-gray-200">
        {title && <h3 className="text-lg font-semibold text-gray-800 mb-4">{title}</h3>}
        <div className="flex justify-center items-center h-64 w-full">
          <svg className="w-48 h-48" viewBox="0 0 100 100">
            {data.map((item, index) => {
              const percentage = (item.value / total) * 100;
              const angle = (percentage / 100) * 360;
              const endAngle = startAngle + angle;

              // Convert angles to radians
              const startRad = (startAngle - 90) * Math.PI / 180;
              const endRad = (endAngle - 90) * Math.PI / 180;

              // Calculate coordinates
              const x1 = 50 + 40 * Math.cos(startRad);
              const y1 = 50 + 40 * Math.sin(startRad);
              const x2 = 50 + 40 * Math.cos(endRad);
              const y2 = 50 + 40 * Math.sin(endRad);

              // Large arc flag
              const largeArcFlag = angle > 180 ? 1 : 0;

              const pathData = [
                `M 50 50`,
                `L ${x1} ${y1}`,
                `A 40 40 0 ${largeArcFlag} 1 ${x2} ${y2}`,
                `Z`
              ].join(' ');

              startAngle = endAngle;

              return (
                <path
                  key={index}
                  d={pathData}
                  fill={`hsl(${index * 60}, 70%, 60%)`}
                  stroke="#fff"
                  strokeWidth="1"
                />
              );
            })}
          </svg>
        </div>
        <div className="mt-4 flex flex-wrap justify-center gap-2">
          {data.map((item, index) => (
            <div key={index} className="flex items-center">
              <div 
                className="w-3 h-3 rounded-full mr-1"
                style={{ backgroundColor: `hsl(${index * 60}, 70%, 60%)` }}
              />
              <span className="text-xs text-gray-600">{item.label}</span>
            </div>
          ))}
        </div>
      </div>
    );
  }

  // Default to bar chart if type is not recognized
  const defaultMaxValue = Math.max(...data.map(item => item.value));

  return (
    <div className="p-6 bg-white rounded-lg shadow-md border border-gray-200">
      {title && <h3 className="text-lg font-semibold text-gray-800 mb-4">{title}</h3>}
      <div className="flex items-end justify-between h-64 space-x-2">
        {data.map((item, index) => (
          <div key={index} className="flex flex-col items-center flex-1">
            <div 
              className={`${config.color} rounded-t w-full transition-all duration-300 hover:opacity-75`}
              style={{ height: `${(item.value / defaultMaxValue) * 100}%` }}
            />
            <span className="mt-2 text-xs text-gray-600 text-center">{item.label}</span>
          </div>
        ))}
      </div>
    </div>
  );
};

export default ChartComponent;",
    "index.html": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Fitness Tracker</title>
  <script src="https://unpkg.com/react@17/umd/react.development.js"></script>
  <script src="https://unpkg.com/react-dom@17/umd/react-dom.development.js"></script>
  <script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>
  <script src="https://cdn.tailwindcss.com"></script>
</head>
<body class="bg-gray-100 min-h-screen">
  <div id="root" class="container mx-auto px-4 py-8"></div>

  <script type="text/babel">
    const { useState, useEffect } = React;

    // Main App Component
    function App() {
      const [workouts, setWorkouts] = useState([]);
      const [exercises, setExercises] = useState([]);
      const [activeTab, setActiveTab] = useState('workouts');

      // Fetch workouts
      useEffect(() => {
        fetch('/api-get-workouts')
          .then(response => response.json())
          .then(data => setWorkouts(data))
          .catch(error => console.error('Error fetching workouts:', error));
      }, []);

      // Fetch exercises
      useEffect(() => {
        fetch('/api-get-exercises')
          .then(response => response.json())
          .then(data => setExercises(data))
          .catch(error => console.error('Error fetching exercises:', error));
      }, []);

      // Create workout
      const createWorkout = (workoutData) => {
        fetch('/api-create-workout', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(workoutData)
        })
        .then(response => response.json())
        .then(data => {
          setWorkouts([...workouts, data]);
        })
        .catch(error => console.error('Error creating workout:', error));
      };

      // Create exercise
      const createExercise = (exerciseData) => {
        fetch('/api-create-exercise', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(exerciseData)
        })
        .then(response => response.json())
        .then(data => {
          setExercises([...exercises, data]);
        })
        .catch(error => console.error('Error creating exercise:', error));
      };

      // Update exercise
      const updateExercise = (id, exerciseData) => {
        fetch(`/api-update-exercise/${id}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(exerciseData)
        })
        .then(response => response.json())
        .then(data => {
          setExercises(exercises.map(ex => ex.id === id ? data : ex));
        })
        .catch(error => console.error('Error updating exercise:', error));
      };

      // Delete exercise
      const deleteExercise = (id) => {
        fetch(`/api-delete-exercise/${id}`, {
          method: 'DELETE'
        })
        .then(() => {
          setExercises(exercises.filter(ex => ex.id !== id));
        })
        .catch(error => console.error('Error deleting exercise:', error));
      };

      return (
        <div className="max-w-6xl mx-auto">
          <header className="bg-blue-600 text-white p-6 rounded-lg shadow-md mb-8">
            <h1 className="text-3xl font-bold">Fitness Tracker</h1>
            <p className="mt-2">Track your workouts and exercises</p>
          </header>

          <div className="flex border-b border-gray-300 mb-6">
            <button 
              className={`py-2 px-4 font-medium ${activeTab === 'workouts' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-gray-600 hover:text-blue-500'}`}
              onClick={() => setActiveTab('workouts')}
            >
              Workouts
            </button>
            <button 
              className={`py-2 px-4 font-medium ${activeTab === 'exercises' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-gray-600 hover:text-blue-500'}`}
              onClick={() => setActiveTab('exercises')}
            >
              Exercises
            </button>
          </div>

          {activeTab === 'workouts' ? (
            <WorkoutList workouts={workouts} />
          ) : (
            <ExerciseList 
              exercises={exercises} 
              onCreateExercise={createExercise}
              onUpdateExercise={updateExercise}
              onDeleteExercise={deleteExercise}
            />
          )}
        </div>
      );
    }

    // Workout List Component
    function WorkoutList({ workouts }) {
      return (
        <div className="bg-white rounded-lg shadow-md p-6">
          <h2 className="text-xl font-bold text-gray-800 mb-4">Workouts</h2>
          {workouts.length === 0 ? (
            <p className="text-gray-600">No workouts found. Create your first workout!</p>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {workouts.map(workout => (
                <div key={workout.id} className="border border-gray-200 rounded-lg p-4 hover:shadow-md transition-shadow">
                  <h3 className="font-bold text-lg text-gray-800">{workout.name}</h3>
                  <p className="text-gray-600 text-sm mt-1">{workout.description}</p>
                  <div className="mt-2 flex justify-between items-center">
                    <span className="text-xs bg-blue-100 text-blue-800 px-2 py-1 rounded">{workout.duration} min</span>
                    <span className="text-xs bg-green-100 text-green-800 px-2 py-1 rounded">{workout.type}</span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      );
    }

    // Exercise List Component
    function ExerciseList({ exercises, onCreateExercise, onUpdateExercise, onDeleteExercise }) {
      const [showForm, setShowForm] = useState(false);
      const [editingId, setEditingId] = useState(null);
      const [formData, setFormData] = useState({
        name: '',
        description: '',
        category: '',
        sets: '',
        reps: '',
        weight: ''
      });

      const handleInputChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
      };

      const handleSubmit = (e) => {
        e.preventDefault();
        if (editingId) {
          onUpdateExercise(editingId, formData);
        } else {
          onCreateExercise(formData);
        }
        resetForm();
      };

      const resetForm = () => {
        setFormData({ name: '', description: '', category: '', sets: '', reps: '', weight: '' });
        setShowForm(false);
        setEditingId(null);
      };

      const handleEdit = (exercise) => {
        setFormData(exercise);
        setEditingId(exercise.id);
        setShowForm(true);
      };

      return (
        <div className="bg-white rounded-lg shadow-md p-6">
          <div className="flex justify-between items-center mb-4">
            <h2 className="text-xl font-bold text-gray-800">Exercises</h2>
            <button 
              onClick={() => setShowForm(!showForm)}
              className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg transition-colors"
            >
              {showForm ? 'Cancel' : 'Add Exercise'}
            </button>
          </div>

          {showForm && (
            <form onSubmit={handleSubmit} className="mb-6 p-4 bg-gray-50 rounded-lg">
              <h3 className="font-medium text-gray-800 mb-3">{editingId ? 'Edit Exercise' : 'Create New Exercise'}</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <input 
                  type="text" 
                  name="name" 
                  placeholder="Exercise Name"
                  value={formData.name}
                  onChange={handleInputChange}
                  className="border border-gray-300 rounded px-3 py-2"
                  required
                />
                <input 
                  type="text" 
                  name="category" 
                  placeholder="Category"
                  value={formData.category}
                  onChange={handleInputChange}
                  className="border border-gray-300 rounded px-3 py-2"
                  required
                />
                <textarea 
                  name="description" 
                  placeholder="Description"
                  value={formData.description}
                  onChange={handleInputChange}
                  className="border border-gray-300 rounded px-3 py-2 col-span-2"
                />
                <input 
                  type="number" 
                  name="sets" 
                  placeholder="Sets"
                  value={formData.sets}
                  onChange={handleInputChange}
                  className="border border-gray-300 rounded px-3 py-2"
                />
                <input 
                  type="number" 
                  name="reps" 
                  placeholder="Reps"
                  value={formData.reps}
                  onChange={handleInputChange}
                  className="border border-gray-300 rounded px-3 py-2"
                />
                <input 
                  type="number" 
                  name="weight" 
                  placeholder="Weight (kg)"
                  value={formData.weight}
                  onChange={handleInputChange}
                  className="border border-gray-300 rounded px-3 py-2"
                />
              </div>
              <div className="mt-4 flex justify-end">
                <button 
                  type="submit" 
                  className="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-lg transition-colors"
                >
                  {editingId ? 'Update Exercise' : 'Create Exercise'}
                </button>
              </div>
            </form>
          )}

          {exercises.length === 0 ? (
            <p className="text-gray-600">No exercises found. Add your first exercise!</p>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {exercises.map(exercise => (
