  "Coder": {
    "src/utils/storageManager.js": "class StorageManager {\n  constructor() {\n    this.workoutsKey = 'workouts';\n    this.exercisesKey = 'exercises';\n  }\n\n  // Workout operations\n  createWorkout(workout) {\n    const workouts = this.getWorkouts();\n    const newWorkout = {\n      ...workout,\n      id: Date.now().toString(),\n      createdAt: new Date().toISOString()\n    };\n    workouts.push(newWorkout);\n    this.setWorkouts(workouts);\n    return newWorkout;\n  }\n\n  getWorkouts() {\n    const workouts = localStorage.getItem(this.workoutsKey);\n    return workouts ? JSON.parse(workouts) : [];\n  }\n\n  updateWorkout(id, updates) {\n    const workouts = this.getWorkouts();\n    const index = workouts.findIndex(w => w.id === id);\n    if (index !== -1) {\n      workouts[index] = { ...workouts[index], ...updates };\n      this.setWorkouts(workouts);\n      return workouts[index];\n    }\n    return null;\n  }\n\n  deleteWorkout(id) {\n    const workouts = this.getWorkouts();\n    const filteredWorkouts = workouts.filter(w => w.id !== id);\n    this.setWorkouts(filteredWorkouts);\n    return filteredWorkouts;\n  }\n\n  // Exercise operations\n  createExercise(exercise) {\n    const exercises = this.getExercises();\n    const newExercise = {\n      ...exercise,\n      id: Date.now().toString(),\n      createdAt: new Date().toISOString()\n    };\n    exercises.push(newExercise);\n    this.setExercises(exercises);\n    return newExercise;\n  }\n\n  getExercises() {\n    const exercises = localStorage.getItem(this.exercisesKey);\n    return exercises ? JSON.parse(exercises) : [];\n  }\n\n  updateExercise(id, updates) {\n    const exercises = this.getExercises();\n    const index = exercises.findIndex(e => e.id === id);\n    if (index !== -1) {\n      exercises[index] = { ...exercises[index], ...updates };\n      this.setExercises(exercises);\n      return exercises[index];\n    }\n    return null;\n  }\n\n  deleteExercise(id) {\n    const exercises = this.getExercises();\n    const filteredExercises = exercises.filter(e => e.id !== id);\n    this.setExercises(filteredExercises);\n    return filteredExercises;\n  }\n\n  // Private methods\n  setWorkouts(workouts) {\n    localStorage.setItem(this.workoutsKey, JSON.stringify(workouts));\n  }\n\n  setExercises(exercises) {\n    localStorage.setItem(this.exercisesKey, JSON.stringify(exercises));\n  }\n}\n\n// Export singleton instance\nconst storageManager = new StorageManager();\nexport default storageManager;",
    "src/utils/dataProcessor.js": "export const processWorkoutData = (workouts) => {\n  if (!workouts || !Array.isArray(workouts)) {\n    return [];\n  }\n\n  // Process workouts for chart rendering\n  const chartData = workouts.map(workout => ({\n    date: new Date(workout.date).toLocaleDateString(),\n    duration: workout.duration,\n    calories: workout.calories,\n    type: workout.type\n  }));\n\n  // Process workouts for history display\n  const historyData = workouts.map(workout => ({\n    id: workout.id,\n    date: new Date(workout.date).toLocaleDateString(),\n    duration: workout.duration,\n    calories: workout.calories,\n    type: workout.type,\n    notes: workout.notes || ''\n  }));\n\n  return {\n    chartData,\n    historyData\n  };\n};\n\nexport const getWorkoutSummary = (workouts) => {\n  if (!workouts || !Array.isArray(workouts)) {\n    return {\n      totalWorkouts: 0,\n      totalDuration: 0,\n      totalCalories: 0,\n      averageDuration: 0\n    };\n  }\n\n  const totalWorkouts = workouts.length;\n  const totalDuration = workouts.reduce((sum, workout) => sum + workout.duration, 0);\n  const totalCalories = workouts.reduce((sum, workout) => sum + workout.calories, 0);\n  const averageDuration = totalWorkouts > 0 ? Math.round(totalDuration / totalWorkouts) : 0;\n\n  return {\n    totalWorkouts,\n    totalDuration,\n    totalCalories,\n    averageDuration\n  };\n};",
    "src/components/workoutForm.js": "import React, { useState } from 'react';\n\nconst WorkoutForm = () => {\n  const [workoutData, setWorkoutData] = useState({\n    name: '',\n    type: '',\n    duration: '',\n    calories: '',\n    date: ''\n  });\n\n  const [isSubmitting, setIsSubmitting] = useState(false);\n  const [submitSuccess, setSubmitSuccess] = useState(false);\n  const [submitError, setSubmitError] = useState('');\n\n  const handleChange = (e) => {\n    const { name, value } = e.target;\n    setWorkoutData(prev => ({\n      ...prev,\n      [name]: value\n    }));\n  };\n\n  const handleSubmit = async (e) => {\n    e.preventDefault();\n    setIsSubmitting(true);\n    setSubmitError('');\n    setSubmitSuccess(false);\n\n    try {\n      const response = await fetch('/api-create-workout', {\n        method: 'POST',\n        headers: {\n          'Content-Type': 'application/json',\n        },\n        body: JSON.stringify(workoutData)\n      });\n\n      if (!response.ok) {\n        throw new Error(`Error: ${response.status}`);\n      }\n\n      setSubmitSuccess(true);\n      // Reset form after successful submission\n      setWorkoutData({\n        name: '',\n        type: '',\n        duration: '',\n        calories: '',\n        date: ''\n      });\n    } catch (error) {\n      setSubmitError(error.message);\n    } finally {\n      setIsSubmitting(false);\n    }\n  };\n\n  return (\n    <div className=\"max-w-md mx-auto p-6 bg-white rounded-lg shadow-md\">\n      <h2 className=\"text-2xl font-bold text-gray-800 mb-4\">Record New Workout</h2>\n      \n      {submitSuccess && (\n        <div className=\"mb-4 p-3 bg-green-100 text-green-700 rounded\">\n          Workout recorded successfully!\n        </div>\n      )}\n      \n      {submitError && (\n        <div className=\"mb-4 p-3 bg-red-100 text-red-700 rounded\">\n          {submitError}\n        </div>\n      )}\n      \n      <form onSubmit={handleSubmit} className=\"space-y-4\">\n        <div>\n          <label htmlFor=\"name\" className=\"block text-sm font-medium text-gray-700 mb-1\">\n            Workout Name\n          </label>\n          <input\n            type=\"text\"\n            id=\"name\"\n            name=\"name\"\n            value={workoutData.name}\n            onChange={handleChange}\n            required\n            className=\"w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500\"\n            placeholder=\"e.g., Morning Run\"\n          />\n        </div>\n        \n        <div>\n          <label htmlFor=\"type\" className=\"block text-sm font-medium text-gray-700 mb-1\">\n            Workout Type\n          </label>\n          <select\n            id=\"type\"\n            name=\"type\"\n            value={workoutData.type}\n            onChange={handleChange}\n            required\n            className=\"w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500\"\n          >\n            <option value=\"\">Select a type</option>\n            <option value=\"running\">Running</option>\n            <option value=\"cycling\">Cycling</option>\n            <option value=\"swimming\">Swimming</option>\n            <option value=\"weightlifting\">Weight Lifting</option>\n            <option value=\"yoga\">Yoga</option>\n            <option value=\"other\">Other</option>\n          </select>\n        </div>\n        \n        <div className=\"grid grid-cols-2 gap-4\">\n          <div>\n            <label htmlFor=\"duration\" className=\"block text-sm font-medium text-gray-700 mb-1\">\n              Duration (minutes)\n            </label>\n            <input\n              type=\"number\"\n              id=\"duration\"\n              name=\"duration\"\n              value={workoutData.duration}\n              onChange={handleChange}\n              required\n              min=\"1\"\n              className=\"w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500\"\n              placeholder=\"e.g., 30\"\n            />\n          </div>\n          \n          <div>\n            <label htmlFor=\"calories\" className=\"block text-sm font-medium text-gray-700 mb-1\">\n              Calories Burned\n            </label>\n            <input\n              type=\"number\"\n              id=\"calories\"\n              name=\"calories\"\n              value={workoutData.calories}\n              onChange={handleChange}\n              required\n              min=\"1\"\n              className=\"w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500\"\n              placeholder=\"e.g., 300\"\n            />\n          </div>\n        </div>\n        \n        <div>\n          <label htmlFor=\"date\" className=\"block text-sm font-medium text-gray-700 mb-1\">\n            Date\n          </label>\n          <input\n            type=\"date\"\n            id=\"date\"\n            name=\"date\"\n            value={workoutData.date}\n            onChange={handleChange}\n            required\n            className=\"w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500\"\n          />\n        </div>\n        \n        <button\n          type=\"submit\"\n          disabled={isSubmitting}\n          className={`w-full py-2 px-4 rounded-md text-white font-medium ${isSubmitting ? 'bg-gray-400' : 'bg-blue-600 hover:bg-blue-700'} transition-colors duration-200`}\n        >\n          {isSubmitting ? 'Recording...' : 'Record Workout'}\n        </button>\n      </form>\n    </div>\n  );\n};\n\nexport default WorkoutForm;",
    "src/components/exerciseList.js": "import React, { useState, useEffect } from 'react';\n\nconst ExerciseList = () => {\n  const [exercises, setExercises] = useState([]);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState(null);\n  const [newExercise, setNewExercise] = useState({\n    name: '',\n    description: '',\n    category: '',\n    difficulty: 'beginner'\n  });\n  const [editingId, setEditingId] = useState(null);\n  const [editForm, setEditForm] = useState({\n    name: '',\n    description: '',\n    category: '',\n    difficulty: 'beginner'\n  });\n\n  // Fetch exercises on component mount\n  useEffect(() => {\n    fetchExercises();\n  }, []);\n\n  const fetchExercises = async () => {\n    try {\n      setLoading(true);\n      const response = await fetch('/api/get-exercises');\n      if (!response.ok) {\n        throw new Error('Failed to fetch exercises');\n      }\n      const data = await response.json();\n      setExercises(data);\n      setError(null);\n    } catch (err) {\n      setError(err.message);\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  const handleCreateExercise = async (e) => {\n    e.preventDefault();\n    try {\n      const response = await fetch('/api/create-exercise', {\n        method: 'POST',\n        headers: {\n          'Content-Type': 'application/json',\n        },\n        body: JSON.stringify(newExercise),\n      });\n\n      if (!response.ok) {\n        throw new Error('Failed to create exercise');\n      }\n\n      const createdExercise = await response.json();\n      setExercises([...exercises, createdExercise]);\n      setNewExercise({\n        name: '',\n        description: '',\n        category: '',\n        difficulty: 'beginner'\n      });\n    } catch (err) {\n      setError(err.message);\n    }\n  };\n\n  const handleUpdateExercise = async (e) => {\n    e.preventDefault();\n    try {\n      const response = await fetch(`/api/update-exercise/${editingId}`, {\n        method: 'PUT',\n        headers: {\n          'Content-Type': 'application/json',\n        },\n        body: JSON.stringify(editForm),\n      });\n\n      if (!response.ok) {\n        throw new Error('Failed to update exercise');\n      }\n\n      const updatedExercise = await response.json();\n      setExercises(exercises.map(ex => ex.id === editingId ? updatedExercise : ex));\n      setEditingId(null);\n      setEditForm({\n        name: '',\n        description: '',\n        category: '',\n        difficulty: 'beginner'\n      });\n    } catch (err) {\n      setError(err.message);\n    }\n  };\n\n  const handleDeleteExercise = async (id) => {\n    try {\n      const response = await fetch(`/api/delete-exercise/${id}`, {\n        method: 'DELETE',\n      });\n\n      if (!response.ok) {\n        throw new Error('Failed to delete exercise');\n      }\n\n      setExercises(exercises.filter(ex => ex.id !== id));\n    } catch (err) {\n      setError(err.message);\n    }\n  };\n\n  const startEditing = (exercise) => {\n    setEditingId(exercise.id);\n    setEditForm({\n      name: exercise.name,\n      description: exercise.description,\n      category: exercise.category,\n      difficulty: exercise.difficulty\n    });\n  };\n\n  const cancelEditing = () => {\n    setEditingId(null);\n    setEditForm({\n      name: '',\n      description: '',\n      category: '',\n      difficulty: 'beginner'\n    });\n  };\n\n  if (loading) {\n    return <div className=\"text-center py-8\">Loading exercises...</div>;\n  }\n\n  if (error) {\n    return (\n      <div className=\"bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded relative\" role=\"alert\">\n        <strong className=\"font-bold\">Error! </strong>\n        <span className=\"block sm:inline\">{error}</span>\n      </div>\n    );\n  }\n\n  return (\n    <div className=\"max-w-6xl mx-auto px-4 py-8\">\n      <h1 className=\"text-3xl font-bold text-gray-800 mb-6\">Custom Exercises</h1>\n\n      {/* Create Exercise Form */}\n      <div className=\"bg-white shadow-md rounded-lg p-6 mb-8\">\n        <h2 className=\"text-xl font-semibold text-gray-700 mb-4\">Create New Exercise</h2>\n        <form onSubmit={handleCreateExercise} className=\"space-y-4\">\n          <div>\n            <label className=\"block text-sm font-medium text-gray-700 mb-1\">Name</label>\n            <input\n              type=\"text\"\n              value={newExercise.name}\n              onChange={(e) => setNewExercise({...newExercise, name: e.target.value})}\n              className=\"w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500\"\n              required\n            />\n          </div>\n          \n          <div>\n            <label className=\"block text-sm font-medium text-gray-700 mb-1\">Description</label>\n            <textarea\n              value={newExercise.description}\n              onChange={(e) => setNewExercise({...newExercise, description: e.target.value})}\n              className=\"w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500\"\n              rows=\"3\"\n            />\n          </div>\n          \n          <div>\n            <label className=\"block text-sm font-medium text-gray-700 mb-1\">Category</label>\n            <input\n              type=\"text\"\n              value={newExercise.category}\n              onChange={(e) => setNewExercise({...newExercise, category: e.target.value})}\n              className=\"w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500\"\n              required\n            />\n          </div>\n          \n          <div>\n            <label className=\"block text-sm font-medium text-gray-700 mb-1\">Difficulty</label>\n            <select\n              value={newExercise.difficulty}\n              onChange={(e) => setNewExercise({...newExercise, difficulty: e.target.value})}\n              className=\"w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500\"\n            >\n              <option value=\"beginner\">Beginner</option>\n              <option value=\"intermediate\">Intermediate</option>\n              <option value=\"advanced\">Advanced</option>\n            </select>\n          </div>\n          \n          <button\n            type=\"submit\"\n            className=\"bg-blue-600 hover:bg-blue-700 text-white font-medium py-2 px-4 rounded-md transition duration-200\"\n          >\n            Create Exercise\n          </button>\n        </form>\n      </div>\n\n      {/* Exercises List */}\n      <div className=\"bg-white shadow-md rounded-lg overflow-hidden\">\n        <h2 className=\"text-xl font-semibold text-gray-700 p-6 border-b\">Your Exercises</h2>\n        \n        {exercises.length === 0 ? (\n          <div className=\"p-6 text-center text-gray-500\">\n            No exercises found. Create your first exercise above.\n          </div>\n        ) : (\n          <ul className=\"divide-y divide-gray-200\">\n            {exercises.map((exercise) => (\n              <li key={exercise.id} className=\"p-6 hover:bg-gray-50 transition duration-150\">\n                {editingId === exercise.id ? (\n                  // Edit Form\n                  <form onSubmit={handleUpdateExercise} className=\"space-y-4\">\n                    <div>\n                      <label className=\"block text-sm font-medium text-gray-700 mb-1\">Name</label>\n                      <input\n                        type=\"text\"\n                        value={editForm.name}\n                        onChange={(e) => setEditForm({...editForm, name: e.target.value})}\n                        className=\"w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500\"\n                        required\n                      />\n                    </div>\n                    \n                    <div>\n                      <label className=\"block text-sm font-medium text-gray-700 mb-1\">Description</label>\n                      <textarea\n                        value={editForm.description}\n                        onChange={(e) => setEditForm({...editForm, description: e.target.value})}\n                        className=\"w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500\"\n                        rows=\"2\"\n                      />\n                    </div>\n                    \n                    <div>\n                      <label className=\"block text-sm font-medium text-gray-700 mb-1\">Category</label>\n                      <input\n                        type=\"text\"\n                        value={editForm.category}\n                        onChange={(e) => setEditForm({...editForm, category: e.target.value})}\n                        className=\"w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500\"\n                        required\n                      />\n                    </div>\n                    \n                    <div>\n                      <label className=\"block text-sm font-medium text-gray-700 mb-1\">Difficulty</label>\n                      <select\n                        value={editForm.difficulty}\n                        onChange={(e) => setEditForm({...editForm, difficulty: e.target.value})}\n                        className=\"w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500\"\n                      >\n                        <option value=\"beginner\">Beginner</option>\n                        <option value=\"intermediate\">Intermediate</option>\n                        <option value=\"advanced\">Advanced</option>\n                      </select>\n                    </div>\n                    \n                    <div className=\"flex space-x-2\">\n                      <button\n                        type=\"submit\"\n                        className=\"bg-green-600 hover:bg-green-700 text-white font-medium py-1 px-3 rounded-md transition duration-200\"\n                      >\n                        Update\n                      </button>\n                      <button\n                        type=\"button\"\n                        onClick={cancelEditing}\n                        className=\"bg-gray-500 hover:bg-gray-600 text-white font-medium py-1 px-3 rounded-md transition duration-200\"\n                      >\n                        Cancel\n                      </button>\n                    </div>\n                  </form>\n                ) : (\n                  // Exercise Display\n                  <div className=\"flex justify-between items-start\">\n                    <div>\n                      <h3 className=\"text-lg font-semibold text-gray-800\">{exercise.name}</h3>\n                      <p className=\"text-gray-600 mt-1\">{exercise.description}</p>\n                      <div className=\"mt-2 flex items-center space-x-4\">\n                        <span className=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-blue-100 text-blue-800\">\n                          {exercise.category}\n                        </span>\n                        <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${\n                          exercise.difficulty === 'beginner' ? 'bg-green-100 text-green-800' : \n                          exercise.difficulty === 'intermediate' ? 'bg-yellow-100 text-yellow-800' : \n                          'bg-red-100 text-red-800'\n                        }`}>\n                          {exercise.difficulty}\n                        </span>\n                      </div>\n                    </div>\n                    <div className=\"flex space-x-2\">\n                      <button\n                        onClick={() => startEditing(exercise)}\n                        className=\"text-blue-600 hover:text-blue-900 font-medium py-1 px-2 rounded-md transition duration-200\"\n                      >\n                        Edit\n                      </button>\n                      <button\n                        onClick={() => handleDeleteExercise(exercise.id)}\n                        className=\"text-red-600 hover:text-red-900 font-medium py-1 px-2 rounded-md transition duration-200\"\n                      >\n                        Delete\n                      </button>\n                    </div>\n                  </div>\n                )}\n              </li>\n            ))}\n          </ul>\n        )}\n      </div>\n    </div>\n  );\n};\n\nexport default ExerciseList;",
    "src/components/historyTable.js": "import React, { useState, useEffect } from 'react';\n\nconst HistoryTable = () => {\n  const [workouts, setWorkouts] = useState([]);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState(null);\n\n  useEffect(() => {\n    const fetchWorkouts = async () => {\n      try {\n        const response = await fetch('/api/get-workouts');\n        if (!response.ok) {\n          throw new Error('Failed to fetch workouts');\n        }\n        const data = await response.json();\n        setWorkouts(data);\n        setLoading(false);\n      } catch (err) {\n        setError(err.message);\n        setLoading(false);\n      }\n    };\n\n    fetchWorkouts();\n  }, []);\n\n  if (loading) {\n    return (\n      <div className=\"flex justify-center items-center h-64\">\n        <div className=\"animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-500\"></div>\n      </div>\n    );\n  }\n\n  if (error) {\n    return (\n      <div className=\"bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded relative\" role=\"alert\">\n        <strong className=\"font-bold\">Error! </strong>\n        <span className=\"block sm:inline\">{error}</span>\n      </div>\n    );\n  }\n\n  return (\n    <div className=\"overflow-x-auto\">\n      <table className=\"min-w-full bg-white border border-gray-200\">\n        <thead>\n          <tr className=\"bg-gray-100 border-b border-gray-200\">\n            <th className=\"py-3 px-6 text-left text-sm font-medium text-gray-700 uppercase tracking-wider\">Date</th>\n            <th className=\"py-3 px-6 text-left text-sm font-medium text-gray-700 uppercase tracking-wider\">Workout Type</th>\n            <th className=\"py-3 px-6 text-left text-sm font-medium text-gray-700 uppercase tracking-wider\">Duration</th>\n            <th className=\"py-3 px-6 text-left text-sm font-medium text-gray-700 uppercase tracking-wider\">Calories Burned</th>\n            <th className=\"py-3 px-6 text-left text-sm font-medium text-gray-700 uppercase tracking-wider\">Status</th>\n          </tr>\n        </thead>\n        <tbody className=\"bg-white\">\n          {workouts.length === 0 ? (\n            <tr>\n              <td colSpan=\"5\" className=\"py-4 px-6 text-center text-gray-500\">No workout history available</td>\n            </tr>\n          ) : (\n            workouts.map((workout) => (\n              <tr key={workout.id} className=\"border-b border-gray-200 hover:bg-gray-50\">\n                <td className=\"py-3 px-6 text-sm text-gray-700\">{new Date(workout.date).toLocaleDateString()}</td>\n                <td className=\"py-3 px-6 text-sm font-medium text-gray-900\">{workout.type}</td>\n                <td className=\"py-3 px-6 text-sm text-gray-700\">{workout.duration} min</td>\n                <td className=\"py-3 px-6 text-sm text-gray-700\">{workout.caloriesBurned}</td>\n                <td className=\"py-3 px-6 text-sm\">\n                  <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full \n                    ${workout.status === 'completed' ? 'bg-green-100 text-green-800' : \n                      workout.status === 'in-progress' ? 'bg-yellow-100 text-yellow-800' : \n                      'bg-red-100 text-red-800'}`}>\n                    {workout.status}\n                  </span>\n                </td>\n              </tr>\n            ))\n          )}\n        </tbody>\n      </table>\n    </div>\n  );\n};\n\nexport default HistoryTable;",
    "src/components/chartComponent.js": "import React from 'react';\n\nconst ChartComponent = ({ data, type = 'bar', title = '' }) => {\n  // Validate data\n  if (!data || !Array.isArray(data) || data.length === 0) {\n    return (\n      <div className=\"p-4 bg-gray-50 rounded-lg border border-gray-200\">\n        <p className=\"text-gray-500 text-center\">No data available for chart</p>\n      </div>\n    );\n  }\n\n  // Prepare chart configuration based on type\n  const chartConfig = {\n    bar: {\n      chartType: 'bar',\n      color: 'bg-blue-500',\n      height: 'h-64',\n    },\n    line: {\n      chartType: 'line',\n      color: 'bg-green-500',\n      height: 'h-64',\n    },\n    pie: {\n      chartType: 'pie',\n      color: 'bg-purple-500',\n      height: 'h-64',\n    },\n  };\n\n  const config = chartConfig[type] || chartConfig.bar;\n\n  // Render bar chart\n  if (config.chartType === 'bar') {\n    const maxValue = Math.max(...data.map(item => item.value));\n    \n    return (\n      <div className=\"p-6 bg-white rounded-lg shadow-md border border-gray-200\">\n        {title && <h3 className=\"text-lg font-semibold text-gray-800 mb-4\">{title}</h3>}\n        <div className=\"flex items-end justify-between h-64 space-x-2\">\n          {data.map((item, index) => (\n            <div key={index} className=\"flex flex-col items-center flex-1\">\n              <div \n                className={`${config.color} rounded-t w-full transition-all duration-300 hover:opacity-75`}\n                style={{ height: `${(item.value / maxValue) * 100}%` }}\n              />\n              <span className=\"mt-2 text-xs text-gray-600 text-center\">{item.label}</span>\n            </div>\n          ))}\n        </div>\n      </div>\n    );\n  }\n\n  // Render line chart\n  if (config.chartType === 'line') {\n    const maxValue = Math.max(...data.map(item => item.value));\n    \n    return (\n      <div className=\"p-6 bg-white rounded-lg shadow-md border border-gray-200\">\n        {title && <h3 className=\"text-lg font-semibold text-gray-800 mb-4\">{title}</h3>}\n        <div className=\"relative h-64 w-full\">\n          <svg className=\"w-full h-full\" viewBox=\"0 0 400 200\">\n            <polyline\n              fill=\"none\"\n              stroke=\"#3B82F6\"\n              strokeWidth=\"2\"\n              points={data.map((item, index) => {\n                const x = (index / (data.length - 1)) * 400;\n                const y = 200 - (item.value / maxValue) * 180;\n                return `${x},${y}`;\n              }).join(' ')}\n            />\n            {data.map((item, index) => {\n              const x = (index / (data.length - 1)) * 400;\n              const y = 200 - (item.value / maxValue) * 180;\n              return (\n                <circle\n                  key={index}\n                  cx={x}\n                  cy={y}\n                  r=\"4\"\n                  fill=\"#3B82F6\"\n                />\n              );\n            })}\n          </svg>\n        </div>\n      </div>\n    );\n  }\n\n  // Render pie chart\n  if (config.chartType === 'pie') {\n    const total = data.reduce((sum, item) => sum + item.value, 0);\n    let startAngle = 0;\n    \n    return (\n      <div className=\"p-6 bg-white rounded-lg shadow-md border border-gray-200\">\n        {title && <h3 className=\"text-lg font-semibold text-gray-800 mb-4\">{title}</h3>}\n        <div className=\"flex justify-center items-center h-64 w-full\">\n          <svg className=\"w-48 h-48\" viewBox=\"0 0 100 100\">\n            {data.map((item, index) => {\n              const percentage = (item.value / total) * 100;\n              const angle = (percentage / 100) * 360;\n              const endAngle = startAngle + angle;\n              \n              // Convert angles to radians\n              const startRad = (startAngle - 90) * Math.PI / 180;\n              const endRad = (endAngle - 90) * Math.PI / 180;\n              \n              // Calculate coordinates\n              const x1 = 50 + 40 * Math.cos(startRad);\n              const y1 = 50 + 40 * Math.sin(startRad);\n              const x2 = 50 + 40 * Math.cos(endRad);\n              const y2 = 50 + 40 * Math.sin(endRad);\n              \n              // Large arc flag\n              const largeArcFlag = angle > 180 ? 1 : 0;\n              \n              const pathData = [\n                `M 50 50`,\n                `L ${x1} ${y1}`,\n                `A 40 40 0 ${largeArcFlag} 1 ${x2} ${y2}`,\n                `Z`\n              ].join(' ');\n              \n              startAngle = endAngle;\n              \n              return (\n                <path\n                  key={index}\n                  d={pathData}\n                  fill={`hsl(${index * 60}, 70%, 60%)`}\n                  stroke=\"#fff\"\n                  strokeWidth=\"1\"\n                />\n              );\n            })}\n          </svg>\n        </div>\n        <div className=\"mt-4 flex flex-wrap justify-center gap-2\">\n          {data.map((item, index) => (\n            <div key={index} className=\"flex items-center\">\n              <div \n                className=\"w-3 h-3 rounded-full mr-1\"\n                style={{ backgroundColor: `hsl(${index * 60}, 70%, 60%)` }}\n              />\n              <span className=\"text-xs text-gray-600\">{item.label}</span>\n            </div>\n          ))}\n        </div>\n      </div>\n    );\n  }\n\n  // Default to bar chart if type is not recognized\n  const defaultMaxValue = Math.max(...data.map(item => item.value));\n  \n  return (\n    <div className=\"p-6 bg-white rounded-lg shadow-md border border-gray-200\">\n      {title && <h3 className=\"text-lg font-semibold text-gray-800 mb-4\">{title}</h3>}\n      <div className=\"flex items-end justify-between h-64 space-x-2\">\n        {data.map((item, index) => (\n          <div key={index} className=\"flex flex-col items-center flex-1\">\n            <div \n              className={`${config.color} rounded-t w-full transition-all duration-300 hover:opacity-75`}\n              style={{ height: `${(item.value / defaultMaxValue) * 100}%` }}\n            />\n            <span className=\"mt-2 text-xs text-gray-600 text-center\">{item.label}</span>\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n};\n\nexport default ChartComponent;",
    "index.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Fitness Tracker</title>\n  <script src=\"https://unpkg.com/react@17/umd/react.development.js\"></script>\n  <script src=\"https://unpkg.com/react-dom@17/umd/react-dom.development.js\"></script>\n  <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n</head>\n<body class=\"bg-gray-100 min-h-screen\">\n  <div id=\"root\" class=\"container mx-auto px-4 py-8\"></div>\n  \n  <script type=\"text/babel\">\n    const { useState, useEffect } = React;\n    \n    // Main App Component\n    function App() {\n      const [workouts, setWorkouts] = useState([]);\n      const [exercises, setExercises] = useState([]);\n      const [activeTab, setActiveTab] = useState('workouts');\n      \n      // Fetch workouts\n      useEffect(() => {\n        fetch('/api-get-workouts')\n          .then(response => response.json())\n          .then(data => setWorkouts(data))\n          .catch(error => console.error('Error fetching workouts:', error));\n      }, []);\n      \n      // Fetch exercises\n      useEffect(() => {\n        fetch('/api-get-exercises')\n          .then(response => response.json())\n          .then(data => setExercises(data))\n          .catch(error => console.error('Error fetching exercises:', error));\n      }, []);\n      \n      // Create workout\n      const createWorkout = (workoutData) => {\n        fetch('/api-create-workout', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify(workoutData)\n        })\n        .then(response => response.json())\n        .then(data => {\n          setWorkouts([...workouts, data]);\n        })\n        .catch(error => console.error('Error creating workout:', error));\n      };\n      \n      // Create exercise\n      const createExercise = (exerciseData) => {\n        fetch('/api-create-exercise', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify(exerciseData)\n        })\n        .then(response => response.json())\n        .then(data => {\n          setExercises([...exercises, data]);\n        })\n        .catch(error => console.error('Error creating exercise:', error));\n      };\n      \n      // Update exercise\n      const updateExercise = (id, exerciseData) => {\n        fetch(`/api-update-exercise/${id}`, {\n          method: 'PUT',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify(exerciseData)\n        })\n        .then(response => response.json())\n        .then(data => {\n          setExercises(exercises.map(ex => ex.id === id ? data : ex));\n        })\n        .catch(error => console.error('Error updating exercise:', error));\n      };\n      \n      // Delete exercise\n      const deleteExercise = (id) => {\n        fetch(`/api-delete-exercise/${id}`, {\n          method: 'DELETE'\n        })\n        .then(() => {\n          setExercises(exercises.filter(ex => ex.id !== id));\n        })\n        .catch(error => console.error('Error deleting exercise:', error));\n      };\n      \n      return (\n        <div className=\"max-w-6xl mx-auto\">\n          <header className=\"bg-blue-600 text-white p-6 rounded-lg shadow-md mb-8\">\n            <h1 className=\"text-3xl font-bold\">Fitness Tracker</h1>\n            <p className=\"mt-2\">Track your workouts and exercises</p>\n          </header>\n          \n          <div className=\"flex border-b border-gray-300 mb-6\">\n            <button \n              className={`py-2 px-4 font-medium ${activeTab === 'workouts' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-gray-600 hover:text-blue-500'}`}\n              onClick={() => setActiveTab('workouts')}\n            >\n              Workouts\n            </button>\n            <button \n              className={`py-2 px-4 font-medium ${activeTab === 'exercises' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-gray-600 hover:text-blue-500'}`}\n              onClick={() => setActiveTab('exercises')}\n            >\n              Exercises\n            </button>\n          </div>\n          \n          {activeTab === 'workouts' ? (\n            <WorkoutList workouts={workouts} />\n          ) : (\n            <ExerciseList \n              exercises={exercises} \n              onCreateExercise={createExercise}\n              onUpdateExercise={updateExercise}\n              onDeleteExercise={deleteExercise}\n            />\n          )}\n        </div>\n      );\n    }\n    \n    // Workout List Component\n    function WorkoutList({ workouts }) {\n      return (\n        <div className=\"bg-white rounded-lg shadow-md p-6\">\n          <h2 className=\"text-xl font-bold text-gray-800 mb-4\">Workouts</h2>\n          {workouts.length === 0 ? (\n            <p className=\"text-gray-600\">No workouts found. Create your first workout!</p>\n          ) : (\n            <div className=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4\">\n              {workouts.map(workout => (\n                <div key={workout.id} className=\"border border-gray-200 rounded-lg p-4 hover:shadow-md transition-shadow\">\n                  <h3 className=\"font-bold text-lg text-gray-800\">{workout.name}</h3>\n                  <p className=\"text-gray-600 text-sm mt-1\">{workout.description}</p>\n                  <div className=\"mt-2 flex justify-between items-center\">\n                    <span className=\"text-xs bg-blue-100 text-blue-800 px-2 py-1 rounded\">{workout.duration} min</span>\n                    <span className=\"text-xs bg-green-100 text-green-800 px-2 py-1 rounded\">{workout.type}</span>\n                  </div>\n                </div>\n              ))}\n            </div>\n          )}\n        </div>\n      );\n    }\n    \n    // Exercise List Component\n    function ExerciseList({ exercises, onCreateExercise, onUpdateExercise, onDeleteExercise }) {\n      const [showForm, setShowForm] = useState(false);\n      const [editingId, setEditingId] = useState(null);\n      const [formData, setFormData] = useState({\n        name: '',\n        description: '',\n        category: '',\n        sets: '',\n        reps: '',\n        weight: ''\n      });\n      \n      const handleInputChange = (e) => {\n        const { name, value } = e.target;\n        setFormData(prev => ({ ...prev, [name]: value }));\n      };\n      \n      const handleSubmit = (e) => {\n        e.preventDefault();\n        if (editingId) {\n          onUpdateExercise(editingId, formData);\n        } else {\n          onCreateExercise(formData);\n        }\n        resetForm();\n      };\n      \n      const resetForm = () => {\n        setFormData({ name: '', description: '', category: '', sets: '', reps: '', weight: '' });\n        setShowForm(false);\n        setEditingId(null);\n      };\n      \n      const handleEdit = (exercise) => {\n        setFormData(exercise);\n        setEditingId(exercise.id);\n        setShowForm(true);\n      };\n      \n      return (\n        <div className=\"bg-white rounded-lg shadow-md p-6\">\n          <div className=\"flex justify-between items-center mb-4\">\n            <h2 className=\"text-xl font-bold text-gray-800\">Exercises</h2>\n            <button \n              onClick={() => setShowForm(!showForm)}\n              className=\"bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg transition-colors\"\n            >\n              {showForm ? 'Cancel' : 'Add Exercise'}\n            </button>\n          </div>\n          \n          {showForm && (\n            <form onSubmit={handleSubmit} className=\"mb-6 p-4 bg-gray-50 rounded-lg\">\n              <h3 className=\"font-medium text-gray-800 mb-3\">{editingId ? 'Edit Exercise' : 'Create New Exercise'}</h3>\n              <div className=\"grid grid-cols-1 md:grid-cols-2 gap-4\">\n                <input \n                  type=\"text\" \n                  name=\"name\" \n                  placeholder=\"Exercise Name\"\n                  value={formData.name}\n                  onChange={handleInputChange}\n                  className=\"border border-gray-300 rounded px-3 py-2\"\n                  required\n                />\n                <input \n                  type=\"text\" \n                  name=\"category\" \n                  placeholder=\"Category\"\n                  value={formData.category}\n                  onChange={handleInputChange}\n                  className=\"border border-gray-300 rounded px-3 py-2\"\n                  required\n                />\n                <textarea \n                  name=\"description\" \n                  placeholder=\"Description\"\n                  value={formData.description}\n                  onChange={handleInputChange}\n                  className=\"border border-gray-300 rounded px-3 py-2 col-span-2\"\n                />\n                <input \n                  type=\"number\" \n                  name=\"sets\" \n                  placeholder=\"Sets\"\n                  value={formData.sets}\n                  onChange={handleInputChange}\n                  className=\"border border-gray-300 rounded px-3 py-2\"\n                />\n                <input \n                  type=\"number\" \n                  name=\"reps\" \n                  placeholder=\"Reps\"\n                  value={formData.reps}\n                  onChange={handleInputChange}\n                  className=\"border border-gray-300 rounded px-3 py-2\"\n                />\n                <input \n                  type=\"number\" \n                  name=\"weight\" \n                  placeholder=\"Weight (kg)\"\n                  value={formData.weight}\n                  onChange={handleInputChange}\n                  className=\"border border-gray-300 rounded px-3 py-2\"\n                />\n              </div>\n              <div className=\"mt-4 flex justify-end\">\n                <button \n                  type=\"submit\" \n                  className=\"bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-lg transition-colors\"\n                >\n                  {editingId ? 'Update Exercise' : 'Create Exercise'}\n                </button>\n              </div>\n            </form>\n          )}\n          \n          {exercises.length === 0 ? (\n            <p className=\"text-gray-600\">No exercises found. Add your first exercise!</p>\n          ) : (\n            <div className=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4\">\n              {exercises.map(exercise => (\n                <div key={exercise.id} className=\"border border-gray-200 rounded-lg p-4 hover:shadow-md transition-shadow\">\n                  <div className=\"flex justify-between items-start\">\n                    <h3 className=\"font-bold text-gray-800\">{exercise.name}</h3>\n                    <div className=\"flex space-x-2\">\n                      <button \n                        onClick={() => handleEdit(exercise)}\n                        className=\"text-blue-600 hover:text-blue-800\"\n                      >\n                        Edit\n                      </button>\n                      <button \n                        onClick={() => onDeleteExercise(exercise.id)}\n                        className=\"text-red-600 hover:text-red-800\"\n                      >\n                        Delete\n                      </button>\n                    </div>\n                  </div>\n                  <p className=\"text-gray-600 text-sm mt-1\">{exercise.description}</p>\n                  <div className=\"mt-2 flex flex-wrap gap-2\">\n                    <span className=\"text-xs bg-purple-100 text-purple-800 px-2 py-1 rounded\">{exercise.category}</span>\n                    {exercise.sets && <span className=\"text-xs bg-yellow-100 text-yellow-800 px-2 py-1 rounded\">{exercise.sets} sets</span>}\n                    {exercise.reps && <span className=\"text-xs bg-yellow-100 text-yellow-800 px-2 py-1 rounded\">{exercise.reps} reps</span>}\n                    {exercise.weight && <span className=\"text-xs bg-yellow-100 text-yellow-800 px-2 py-1 rounded\">{exercise.weight} kg</span>}\n                  </div>\n                </div>\n              ))}\n            </div>\n          )}\n        </div>\n      );\n    }\n    \n    // Render the app\n    ReactDOM.render(<App />, document.getElementById('root'));\n  </script>\n</body>\n</html>",
    "src/app.js": "import { createWorkout } from './api/workout-api.js';\nimport { getWorkouts } from './api/workout-api.js';\nimport { createExercise } from './api/exercise-api.js';\nimport { updateExercise } from './api/exercise-api.js';\nimport { deleteExercise } from './api/exercise-api.js';\nimport { getExercises } from './api/exercise-api.js';\n\n// Main application class to orchestrate modules\nexport class WorkoutApp {\n  constructor() {\n    this.workouts = [];\n    this.exercises = [];\n  }\n\n  async initialize() {\n    try {\n      // Load initial data\n      await this.loadWorkouts();\n      await this.loadExercises();\n      console.log('Application initialized successfully');\n    } catch (error) {\n      console.error('Failed to initialize application:', error);\n      throw error;\n    }\n  }\n\n  async loadWorkouts() {\n    try {\n      this.workouts = await getWorkouts();\n      console.log('Workouts loaded:', this.workouts.length);\n    } catch (error) {\n      console.error('Failed to load workouts:', error);\n      throw error;\n    }\n  }\n\n  async loadExercises() {\n    try {\n      this.exercises = await getExercises();\n      console.log('Exercises loaded:', this.exercises.length);\n    } catch (error) {\n      console.error('Failed to load exercises:', error);\n      throw error;\n    }\n  }\n\n  async createWorkout(workoutData) {\n    try {\n      const newWorkout = await createWorkout(workoutData);\n      this.workouts.push(newWorkout);\n      return newWorkout;\n    } catch (error) {\n      console.error('Failed to create workout:', error);\n      throw error;\n    }\n  }\n\n  async createExercise(exerciseData) {\n    try {\n      const newExercise = await createExercise(exerciseData);\n      this.exercises.push(newExercise);\n      return newExercise;\n    } catch (error) {\n      console.error('Failed to create exercise:', error);\n      throw error;\n    }\n  }\n\n  async updateExercise(id, exerciseData) {\n    try {\n      const updatedExercise = await updateExercise(id, exerciseData);\n      // Update in local array\n      const index = this.exercises.findIndex(ex => ex.id === id);\n      if (index !== -1) {\n        this.exercises[index] = updatedExercise;\n      }\n      return updatedExercise;\n    } catch (error) {\n      console.error('Failed to update exercise:', error);\n      throw error;\n    }\n  }\n\n  async deleteExercise(id) {\n    try {\n      await deleteExercise(id);\n      // Remove from local array\n      this.exercises = this.exercises.filter(ex => ex.id !== id);\n      console.log(`Exercise ${id} deleted`);\n    } catch (error) {\n      console.error('Failed to delete exercise:', error);\n      throw error;\n    }\n  }\n\n  getWorkouts() {\n    return this.workouts;\n  }\n\n  getExercises() {\n    return this.exercises;\n  }\n\n  getWorkoutById(id) {\n    return this.workouts.find(workout => workout.id === id);\n  }\n\n  getExerciseById(id) {\n    return this.exercises.find(exercise => exercise.id === id);\n  }\n}\n\n// Export singleton instance\nexport const app = new WorkoutApp();",
    "src/modules/workoutRecorder.js": "/*\n * Handles creation and saving of new workouts\n */\n\n// API endpoint for creating workouts\nconst CREATE_WORKOUT_API = 'api-create-workout';\n\n/**\n * Creates a new workout object with the provided details\n * @param {Object} workoutData - The data for the new workout\n * @param {string} workoutData.name - Name of the workout\n * @param {string} workoutData.description - Description of the workout\n * @param {Array} workoutData.exercises - Array of exercise objects\n * @param {string} workoutData.date - Date of the workout\n * @returns {Object} The created workout object\n */\nexport function createWorkout(workoutData) {\n  // Validate required fields\n  if (!workoutData.name || !workoutData.date) {\n    throw new Error('Workout name and date are required');\n  }\n\n  // Create the workout object with default values\n  const workout = {\n    id: generateWorkoutId(),\n    name: workoutData.name,\n    description: workoutData.description || '',\n    exercises: workoutData.exercises || [],\n    date: workoutData.date,\n    createdAt: new Date().toISOString(),\n    updatedAt: new Date().toISOString()\n  };\n\n  return workout;\n}\n\n/**\n * Saves a workout to the backend\n * @param {Object} workout - The workout object to save\n * @returns {Promise<Object>} The saved workout object\n */\nexport async function saveWorkout(workout) {\n  try {\n    // Validate workout object\n    if (!workout || !workout.id) {\n      throw new Error('Invalid workout object');\n    }\n\n    // Update the updatedAt timestamp\n    workout.updatedAt = new Date().toISOString();\n\n    // Make API call to save workout\n    const response = await fetch(CREATE_WORKOUT_API, {\n      method: 'POST',\n      headers: {\n        'Content-Type': 'application/json'\n      },\n      body: JSON.stringify(workout)\n    });\n\n    if (!response.ok) {\n      throw new Error(`Failed to save workout: ${response.status}`);\n    }\n\n    const savedWorkout = await response.json();\n    return savedWorkout;\n  } catch (error) {\n    console.error('Error saving workout:', error);\n    throw error;\n  }\n}\n\n/**\n * Generates a unique ID for a workout\n * @returns {string} A unique workout ID\n */\nfunction generateWorkoutId() {\n  // Simple UUID-like ID generation\n  return 'workout-' + Date.now() + '-' + Math.random().toString(36).substr(2, 9);\n}\n\n/**\n * Adds an exercise to a workout\n * @param {Object} workout - The workout object\n * @param {Object} exercise - The exercise to add\n * @returns {Object} The updated workout object\n */\nexport function addExerciseToWorkout(workout, exercise) {\n  if (!workout.exercises) {\n    workout.exercises = [];\n  }\n\n  workout.exercises.push({\n    id: generateExerciseId(),\n    ...exercise,\n    createdAt: new Date().toISOString()\n  });\n\n  return workout;\n}\n\n/**\n * Generates a unique ID for an exercise\n * @returns {string} A unique exercise ID\n */\nfunction generateExerciseId() {\n  // Simple UUID-like ID generation\n  return 'exercise-' + Date.now() + '-' + Math.random().toString(36).substr(2, 9);\n}\n\n/**\n * Removes an exercise from a workout\n * @param {Object} workout - The workout object\n * @param {string} exerciseId - The ID of the exercise to remove\n * @returns {Object} The updated workout object\n */\nexport function removeExerciseFromWorkout(workout, exerciseId) {\n  if (workout.exercises) {\n    workout.exercises = workout.exercises.filter(exercise => exercise.id !== exerciseId);\n  }\n\n  return workout;\n}\n\n/**\n * Updates a workout in the backend\n * @param {Object} workout - The workout object to update\n * @returns {Promise<Object>} The updated workout object\n */\nexport async function updateWorkout(workout) {\n  try {\n    // Validate workout object\n    if (!workout || !workout.id) {\n      throw new Error('Invalid workout object');\n    }\n\n    // Update the updatedAt timestamp\n    workout.updatedAt = new Date().toISOString();\n\n    // Make API call to update workout\n    const response = await fetch(`${CREATE_WORKOUT_API}/${workout.id}`, {\n      method: 'PUT',\n      headers: {\n        'Content-Type': 'application/json'\n      },\n      body: JSON.stringify(workout)\n    });\n\n    if (!response.ok) {\n      throw new Error(`Failed to update workout: ${response.status}`);\n    }\n\n    const updatedWorkout = await response.json();\n    return updatedWorkout;\n  } catch (error) {\n    console.error('Error updating workout:', error);\n    throw error;\n  }\n}\n\n/**\n * Deletes a workout from the backend\n * @param {string} workoutId - The ID of the workout to delete\n * @returns {Promise<boolean>} True if deletion was successful\n */\nexport async function deleteWorkout(workoutId) {\n  try {\n    // Make API call to delete workout\n    const response = await fetch(`${CREATE_WORKOUT_API}/${workoutId}`, {\n      method: 'DELETE'\n    });\n\n    if (!response.ok) {\n      throw new Error(`Failed to delete workout: ${response.status}`);\n    }\n\n    return true;\n  } catch (error) {\n    console.error('Error deleting workout:', error);\n    throw error;\n  }\n}",
    "src/modules/exerciseManager.js": "class ExerciseManager {\n  constructor() {\n    this.exercises = [];\n    this.nextId = 1;\n  }\n\n  // API: api-create-exercise\n  createExercise(exerciseData) {\n    const exercise = {\n      id: this.nextId++,\n      ...exerciseData,\n      createdAt: new Date().toISOString(),\n      updatedAt: new Date().toISOString()\n    };\n\n    this.exercises.push(exercise);\n    return exercise;\n  }\n\n  // API: api-get-exercises\n  getExercises() {\n    return this.exercises;\n  }\n\n  // API: api-update-exercise\n  updateExercise(id, exerciseData) {\n    const index = this.exercises.findIndex(ex => ex.id === id);\n    \n    if (index === -1) {\n      throw new Error('Exercise not found');\n    }\n\n    this.exercises[index] = {\n      ...this.exercises[index],\n      ...exerciseData,\n      updatedAt: new Date().toISOString()\n    };\n\n    return this.exercises[index];\n  }\n\n  // API: api-delete-exercise\n  deleteExercise(id) {\n    const index = this.exercises.findIndex(ex => ex.id === id);\n    \n    if (index === -1) {\n      throw new Error('Exercise not found');\n    }\n\n    return this.exercises.splice(index, 1)[0];\n  }\n}\n\n// Export the ExerciseManager class\nexport default ExerciseManager;",
    "src/modules/historyLogger.js": "import { apiGetWorkouts } from '../api/workoutApi.js';\n\nexport class HistoryLogger {\n  constructor() {\n    this.workouts = [];\n    this.tableElement = null;\n  }\n\n  async initialize() {\n    try {\n      this.workouts = await apiGetWorkouts();\n      this.renderTable();\n    } catch (error) {\n      console.error('Failed to load workout history:', error);\n      this.showError('Unable to load workout history');\n    }\n  }\n\n  renderTable() {\n    if (!this.workouts || this.workouts.length === 0) {\n      this.showEmptyState();\n      return;\n    }\n\n    const table = document.createElement('table');\n    table.className = 'min-w-full bg-white border border-gray-200';\n\n    const thead = document.createElement('thead');\n    thead.innerHTML = `\n      <tr class=\"bg-gray-100\">\n        <th class=\"py-2 px-4 border-b text-left\">Date</th>\n        <th class=\"py-2 px-4 border-b text-left\">Workout Type</th>\n        <th class=\"py-2 px-4 border-b text-left\">Duration (min)</th>\n        <th class=\"py-2 px-4 border-b text-left\">Calories Burned</th>\n        <th class=\"py-2 px-4 border-b text-left\">Notes</th>\n      </tr>\n    `;\n\n    const tbody = document.createElement('tbody');\n    this.workouts.forEach(workout => {\n      const row = document.createElement('tr');\n      row.className = 'hover:bg-gray-50';\n      row.innerHTML = `\n        <td class=\"py-2 px-4 border-b\">${workout.date}</td>\n        <td class=\"py-2 px-4 border-b\">${workout.type}</td>\n        <td class=\"py-2 px-4 border-b\">${workout.duration}</td>\n        <td class=\"py-2 px-4 border-b\">${workout.calories}</td>\n        <td class=\"py-2 px-4 border-b\">${workout.notes || '-'}</td>\n      `;\n      tbody.appendChild(row);\n    });\n\n    table.appendChild(thead);\n    table.appendChild(tbody);\n\n    if (this.tableElement) {\n      this.tableElement.innerHTML = '';\n      this.tableElement.appendChild(table);\n    } else {\n      this.ta