import { apiGetWorkouts } from '../api/workoutApi.js';

export class HistoryLogger {
  constructor() {
    this.workouts = [];
    this.tableElement = null;
  }

  async initialize() {
    try {
      this.workouts = await apiGetWorkouts();
      this.renderTable();
    } catch (error) {
      console.error('Failed to load workout history:', error);
      this.showError('Unable to load workout history');
    }
  }

  renderTable() {
    if (!this.workouts || this.workouts.length === 0) {
      this.showEmptyState();
      return;
    }

    const table = document.createElement('table');
    table.className = 'min-w-full bg-white border border-gray-200';

    const thead = document.createElement('thead');
    thead.innerHTML = `
      <tr class="bg-gray-100">
        <th class="py-2 px-4 border-b text-left">Date</th>
        <th class="py-2 px-4 border-b text-left">Workout Type</th>
        <th class="py-2 px-4 border-b text-left">Duration (min)</th>
        <th class="py-2 px-4 border-b text-left">Calories Burned</th>
        <th class="py-2 px-4 border-b text-left">Notes</th>
      </tr>
    `;

    const tbody = document.createElement('tbody');
    this.workouts.forEach(workout => {
      const row = document.createElement('tr');
      row.className = 'hover:bg-gray-50';
      row.innerHTML = `
        <td class="py-2 px-4 border-b">${workout.date}</td>
        <td class="py-2 px-4 border-b">${workout.type}</td>
        <td class="py-2 px-4 border-b">${workout.duration}</td>
        <td class="py-2 px-4 border-b">${workout.calories}</td>
        <td class="py-2 px-4 border-b">${workout.notes || '-'}</td>
      `;
      tbody.appendChild(row);
    });

    table.appendChild(thead);
    table.appendChild(tbody);

    if (this.tableElement) {
      this.tableElement.innerHTML = '';
      this.tableElement.appendChild(table);
    } else {
      this.tableElement = document.createElement('div');
      this.tableElement.className = 'overflow-x-auto';
      this.tableElement.appendChild(table);
      document.body.appendChild(this.tableElement);
    }
  }

  showEmptyState() {
    if (this.tableElement) {
      this.tableElement.innerHTML = '<p class="text-gray-500 text-center py-8">No workout history available.</p>';
    } else {
      this.tableElement = document.createElement('div');
      this.tableElement.className = 'text-center py-8';
      this.tableElement.innerHTML = '<p class="text-gray-500">No workout history available.</p>';
      document.body.appendChild(this.tableElement);
    }
  }

  showError(message) {
    if (this.tableElement) {
      this.tableElement.innerHTML = `<p class="text-red-500 text-center py-8">${message}</p>`;
    } else {
      this.tableElement = document.createElement('div');
      this.tableElement.className = 'text-center py-8';
      this.tableElement.innerHTML = `<p class="text-red-500">${message}</p>`;
      document.body.appendChild(this.tableElement);
    }
  }
}

// Export singleton instance
export const historyLogger = new HistoryLogger();

