    if (!Array.isArray(workoutData) || workoutData.length === 0) {
      throw new Error('Invalid workout data provided');
    }

    // Create chart container if it doesn't exist
    let chartContainer = document.getElementById(chartId);
    if (!chartContainer) {
      chartContainer = document.createElement('div');
      chartContainer.id = chartId;
      chartContainer.style.width = '100%';
      chartContainer.style.height = '400px';
      document.body.appendChild(chartContainer);
    }

    // Prepare data for charting library
    const processedData = this.processWorkoutData(workoutData);

    // Generate chart based on type
    let chartInstance;
    switch (type.toLowerCase()) {
      case 'line':
        chartInstance = this.createLineChart(chartContainer, processedData, options);
        break;
      case 'bar':
        chartInstance = this.createBarChart(chartContainer, processedData, options);
        break;
      case 'pie':
        chartInstance = this.createPieChart(chartContainer, processedData, options);
        break;
      default:
        throw new Error(`Unsupported chart type: ${type}`);
    }

    // Store chart instance for potential updates
    this.chartInstances.set(chartId, chartInstance);

    return chartInstance;
  }

  /**
   * Processes raw workout data into chart-friendly format
   * @param {Array} workoutData - Raw workout data
   * @returns {Object} Processed data ready for charting
   */
  processWorkoutData(workoutData) {
    // Group workouts by date (assuming date is in ISO format)
    const groupedByDate = workoutData.reduce((acc, workout) => {
      const date = new Date(workout.date).toISOString().split('T')[0];
      if (!acc[date]) {
        acc[date] = [];
      }
      acc[date].push(workout);
      return acc;
    }, {});

    // Calculate daily totals
    const dailyTotals = Object.entries(groupedByDate).map(([date, workouts]) => ({
      date,
      totalDuration: workouts.reduce((sum, workout) => sum + (workout.duration || 0), 0)
    }));

    // Sort by date
    dailyTotals.sort((a, b) => new Date(a.date) - new Date(b.date));

    return {
      labels: dailyTotals.map(item => item.date),
      datasets: [{
        label: 'Workout Duration (minutes)',
        data: dailyTotals.map(item => item.totalDuration),
        backgroundColor: '#3B82F6',
        borderColor: '#1D4ED8',
        borderWidth: 1
      }]
    };
  }

  /**
   * Creates a line chart
   * @param {HTMLElement} container - DOM element to render chart in
   * @param {Object} data - Chart data
   * @param {Object} options - Chart options
   * @returns {Object} Chart instance
   */
  createLineChart(container, data, options) {
    // Simple line chart implementation using canvas
    const canvas = document.createElement('canvas');
    container.innerHTML = '';
    container.appendChild(canvas);

    const ctx = canvas.getContext('2d');

    // Set canvas dimensions
    canvas.width = container.clientWidth;
    canvas.height = container.clientHeight;

    // Chart configuration
    const config = {
      type: 'line',
      data,
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            title: {
              display: true,
              text: 'Duration (minutes)'
            }
          },
          x: {
            title: {
              display: true,
              text: 'Date'
            }
          }
        },
        plugins: {
          legend: {
            display: true
          },
          title: {
            display: true,
            text: 'Workout History'
          }
        }
      }
    };

    // Return chart instance (simplified for this implementation)
    return {
      type: 'line',
      data,
      options,
      canvas
    };
  }

  /**
   * Creates a bar chart
   * @param {HTMLElement} container - DOM element to render chart in
   * @param {Object} data - Chart data
   * @param {Object} options - Chart options
   * @returns {Object} Chart instance
   */
  createBarChart(container, data, options) {
    // Simple bar chart implementation using canvas
    const canvas = document.createElement('canvas');
    container.innerHTML = '';
    container.appendChild(canvas);

    const ctx = canvas.getContext('2d');

    // Set canvas dimensions
    canvas.width = container.clientWidth;
    canvas.height = container.clientHeight;

    // Chart configuration
    const config = {
      type: 'bar',
      data,
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            title: {
              display: true,
              text: 'Duration (minutes)'
            }
          },
          x: {
            title: {
              display: true,
              text: 'Date'
            }
          }
        },
        plugins: {
          legend: {
            display: true
          },
          title: {
            display: true,
            text: 'Workout History'
          }
        }
      }
    };

    // Return chart instance (simplified for this implementation)
    return {
      type: 'bar',
      data,
      options,
      canvas
    };
  }

  /**
   * Creates a pie chart
   * @param {HTMLElement} container - DOM element to render chart in
   * @param {Object} data - Chart data
   * @param {Object} options - Chart options
   * @returns {Object} Chart instance
   */
  createPieChart(container, data, options) {
    // Simple pie chart implementation using canvas
    const canvas = document.createElement('canvas');
    container.innerHTML = '';
    container.appendChild(canvas);

    const ctx = canvas.getContext('2d');

    // Set canvas dimensions
    canvas.width = container.clientWidth;
    canvas.height = container.clientHeight;

    // Chart configuration
    const config = {
      type: 'pie',
      data,
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            display: true
          },
          title: {
            display: true,
            text: 'Workout Distribution'
          }
        }
      }
    };

    // Return chart instance (simplified for this implementation)
    return {
      type: 'pie',
      data,
      options,
      canvas
    };
  }

  /**
   * Updates an existing chart with new data
   * @param {string} chartId - Unique identifier for the chart
   * @param {Array} newData - New workout data to update chart with
   */
  updateChart(chartId, newData) {
    const chartInstance = this.chartInstances.get(chartId);
    if (!chartInstance) {
      throw new Error(`Chart with ID ${chartId} not found`);
    }

    // Process new data
    const processedData = this.processWorkoutData(newData);

    // Update chart instance (simplified)
    chartInstance.data = processedData;

    return chartInstance;
  }

  /**
   * Removes a chart from the DOM and cleans up references
   * @param {string} chartId - Unique identifier for the chart
   */
  removeChart(chartId) {
    const chartContainer = document.getElementById(chartId);
    if (chartContainer) {
      chartContainer.remove();
    }

    this.chartInstances.delete(chartId);
  }
}

// Export the ChartRenderer class
export default ChartRenderer;"
}

