class StorageManager {
  constructor() {
    this.workoutsKey = 'workouts';
    this.exercisesKey = 'exercises';
  }

  // Workout operations
  createWorkout(workout) {
    const workouts = this.getWorkouts();
    const newWorkout = {
      ...workout,
      id: Date.now().toString(),
      createdAt: new Date().toISOString()
    };
    workouts.push(newWorkout);
    this.setWorkouts(workouts);
    return newWorkout;
  }

  getWorkouts() {
    const workouts = localStorage.getItem(this.workoutsKey);
    return workouts ? JSON.parse(workouts) : [];
  }

  updateWorkout(id, updates) {
    const workouts = this.getWorkouts();
    const index = workouts.findIndex(w => w.id === id);
    if (index !== -1) {
      workouts[index] = { ...workouts[index], ...updates };
      this.setWorkouts(workouts);
      return workouts[index];
    }
    return null;
  }

  deleteWorkout(id) {
    const workouts = this.getWorkouts();
    const filteredWorkouts = workouts.filter(w => w.id !== id);
    this.setWorkouts(filteredWorkouts);
    return filteredWorkouts;
  }

  // Exercise operations
  createExercise(exercise) {
    const exercises = this.getExercises();
    const newExercise = {
      ...exercise,
      id: Date.now().toString(),
      createdAt: new Date().toISOString()
    };
    exercises.push(newExercise);
    this.setExercises(exercises);
    return newExercise;
  }

  getExercises() {
    const exercises = localStorage.getItem(this.exercisesKey);
    return exercises ? JSON.parse(exercises) : [];
  }

  updateExercise(id, updates) {
    const exercises = this.getExercises();
    const index = exercises.findIndex(e => e.id === id);
    if (index !== -1) {
      exercises[index] = { ...exercises[index], ...updates };
      this.setExercises(exercises);
      return exercises[index];
    }
    return null;
  }

  deleteExercise(id) {
    const exercises = this.getExercises();
    const filteredExercises = exercises.filter(e => e.id !== id);
    this.setExercises(filteredExercises);
    return filteredExercises;
  }

  // Private methods
  setWorkouts(workouts) {
    localStorage.setItem(this.workoutsKey, JSON.stringify(workouts));
  }

  setExercises(exercises) {
    localStorage.setItem(this.exercisesKey, JSON.stringify(exercises));
  }
}

// Export singleton instance
const storageManager = new StorageManager();
export default storageManager;

