import { createWorkout } from './api/workout-api.js';
import { getWorkouts } from './api/workout-api.js';
import { createExercise } from './api/exercise-api.js';
import { updateExercise } from './api/exercise-api.js';
import { deleteExercise } from './api/exercise-api.js';
import { getExercises } from './api/exercise-api.js';

// Main application class to orchestrate modules
export class WorkoutApp {
  constructor() {
    this.workouts = [];
    this.exercises = [];
  }

  async initialize() {
    try {
      // Load initial data
      await this.loadWorkouts();
      await this.loadExercises();
      console.log('Application initialized successfully');
    } catch (error) {
      console.error('Failed to initialize application:', error);
      throw error;
    }
  }

  async loadWorkouts() {
