  if (error) {
    return (
      <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded relative" role="alert">
        <strong className="font-bold">Error! </strong>
        <span className="block sm:inline">{error}</span>
      </div>
    );
  }

  return (
    <div className="overflow-x-auto">
      <table className="min-w-full bg-white border border-gray-200">
        <thead>
          <tr className="bg-gray-100 border-b border-gray-200">
            <th className="py-3 px-6 text-left text-sm font-medium text-gray-700 uppercase tracking-wider">Date</th>
            <th className="py-3 px-6 text-left text-sm font-medium text-gray-700 uppercase tracking-wider">Workout Type</th>
            <th className="py-3 px-6 text-left text-sm font-medium text-gray-700 uppercase tracking-wider">Duration</th>
            <th className="py-3 px-6 text-left text-sm font-medium text-gray-700 uppercase tracking-wider">Calories Burned</th>
            <th className="py-3 px-6 text-left text-sm font-medium text-gray-700 uppercase tracking-wider">Status</th>
          </tr>
        </thead>
        <tbody className="bg-white">
          {workouts.length === 0 ? (
            <tr>
              <td colSpan="5" className="py-4 px-6 text-center text-gray-500">No workout history available</td>
            </tr>
          ) : (
            workouts.map((workout) => (
              <tr key={workout.id} className="border-b border-gray-200 hover:bg-gray-50">
                <td className="py-3 px-6 text-sm text-gray-700">{new Date(workout.date).toLocaleDateString()}</td>
                <td className="py-3 px-6 text-sm font-medium text-gray-900">{workout.type}</td>
                <td className="py-3 px-6 text-sm text-gray-700">{workout.duration} min</td>
                <td className="py-3 px-6 text-sm text-gray-700">{workout.caloriesBurned}</td>
                <td className="py-3 px-6 text-sm">
                  <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full 
                    ${workout.status === 'completed' ? 'bg-green-100 text-green-800' : 
                      workout.status === 'in-progress' ? 'bg-yellow-100 text-yellow-800' : 
                      'bg-red-100 text-red-800'}`}>
                    {workout.status}
                  </span>
                </td>
              </tr>
            ))
          )}
        </tbody>
      </table>
    </div>
  );
};

export default HistoryTable;

