/*
 * Handles creation and saving of new workouts
 */

// API endpoint for creating workouts
const CREATE_WORKOUT_API = 'api-create-workout';

/**
 * Creates a new workout object with the provided details
 * @param {Object} workoutData - The data for the new workout
 * @param {string} workoutData.name - Name of the workout
 * @param {string} workoutData.description - Description of the workout
 * @param {Array} workoutData.exercises - Array of exercise objects
 * @param {string} workoutData.date - Date of the workout
 * @returns {Object} The created workout object
 */
export function createWorkout(workoutData) {
  // Validate required fields
  if (!workoutData.name || !workoutData.date) {
    throw new Error('Workout name and date are required');
  }

  // Create the workout object with default values
  const workout = {
    id: generateWorkoutId(),
    name: workoutData.name,
    description: workoutData.description || '',
    exercises: workoutData.exercises || [],
    date: workoutData.date,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  };

  return workout;
}

/**
 * Saves a workout to the backend
 * @param {Object} workout - The workout object to save
 * @returns {Promise<Object>} The saved workout object
 */
export async function saveWorkout(workout) {
  try {
    // Validate workout object
    if (!workout || !workout.id) {
      throw new Error('Invalid workout object');
    }

    // Update the updatedAt timestamp
    workout.updatedAt = new Date().toISOString();

    // Make API call to save workout
    const response = await fetch(CREATE_WORKOUT_API, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(workout)
    });

    if (!response.ok) {
      throw new Error(`Failed to save workout: ${response.status}`);
    }

    const savedWorkout = await response.json();
    return savedWorkout;
  } catch (error) {
    console.error('Error saving workout:', error);
    throw error;
  }
}

/**
 * Generates a unique ID for a workout
 * @returns {string} A unique workout ID
 */
function generateWorkoutId() {
  // Simple UUID-like ID generation
  return 'workout-' + Date.now() + '-' + Math.random().toString(36).substr(2, 9);
}

/**
 * Adds an exercise to a workout
 * @param {Object} workout - The workout object
 * @param {Object} exercise - The exercise to add
 * @returns {Object} The updated workout object
 */
export function addExerciseToWorkout(workout, exercise) {
  if (!workout.exercises) {
    workout.exercises = [];
  }

  workout.exercises.push({
    id: generateExerciseId(),
    ...exercise,
    createdAt: new Date().toISOString()
  });

  return workout;
}

/**
 * Generates a unique ID for an exercise
 * @returns {string} A unique exercise ID
 */
function generateExerciseId() {
  // Simple UUID-like ID generation
  return 'exercise-' + Date.now() + '-' + Math.random().toString(36).substr(2, 9);
}

/**
 * Removes an exercise from a workout
 * @param {Object} workout - The workout object
 * @param {string} exerciseId - The ID of the exercise to remove
 * @returns {Object} The updated workout object
 */
export function removeExerciseFromWorkout(workout, exerciseId) {
  if (workout.exercises) {
    workout.exercises = workout.exercises.filter(exercise => exercise.id !== exerciseId);
  }

  return workout;
}

/**
 * Updates a workout in the backend
 * @param {Object} workout - The workout object to update
 * @returns {Promise<Object>} The updated workout object
 */
export async function updateWorkout(workout) {
  try {
    // Validate workout object
    if (!workout || !workout.id) {
      throw new Error('Invalid workout object');
    }

    // Update the updatedAt timestamp
    workout.updatedAt = new Date().toISOString();

    // Make API call to update workout
    const response = await fetch(`${CREATE_WORKOUT_API}/${workout.id}`, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(workout)
    });

    if (!response.ok) {
      throw new Error(`Failed to update workout: ${response.status}`);
    }

    const updatedWorkout = await response.json();
    return updatedWorkout;
  } catch (error) {
    console.error('Error updating workout:', error);
    throw error;
  }
}

/**
 * Deletes a workout from the backend
 * @param {string} workoutId - The ID of the workout to delete
 * @returns {Promise<boolean>} True if deletion was successful
 */
export async function deleteWorkout(workoutId) {
  try {
    // Make API call to delete workout
    const response = await fetch(`${CREATE_WORKOUT_API}/${workoutId}`, {
      method: 'DELETE'
    });

    if (!response.ok) {
      throw new Error(`Failed to delete workout: ${response.status}`);
    }

    return true;
  } catch (error) {
    console.error('Error deleting workout:', error);
    throw error;
  }
}

