        <td class="py-2 px-4 border-b">${workout.duration}</td>
        <td class="py-2 px-4 border-b">${workout.calories}</td>
        <td class="py-2 px-4 border-b">${workout.notes || '-'}</td>
      `;
      tbody.appendChild(row);
    });

    table.appendChild(thead);
    table.appendChild(tbody);

    if (this.tableElement) {
      this.tableElement.innerHTML = '';
      this.tableElement.appendChild(table);
    } else {
      this.tableElement = document.createElement('div');
      this.tableElement.className = 'overflow-x-auto';
      this.tableElement.appendChild(table);
      document.body.appendChild(this.tableElement);
    }
  }

  showEmptyState() {
    if (this.tableElement) {
      this.tableElement.innerHTML = '<p class="text-gray-500 text-center py-8">No workout history available.</p>';
    } else {
      this.tableElement = document.createElement('div');
      this.tableElement.className = 'text-center py-8';
      this.tableElement.innerHTML = '<p class="text-gray-500">No workout history available.</p>';
      document.body.appendChild(this.tableElement);
    }
  }

  showError(message) {
    if (this.tableElement) {
      this.tableElement.innerHTML = `<p class="text-red-500 text-center py-8">${message}</p>`;
    } else {
      this.tableElement = document.createElement('div');
      this.tableElement.className = 'text-center py-8';
      this.tableElement.innerHTML = `<p class="text-red-500">${message}</p>`;
      document.body.appendChild(this.tableElement);
    }
  }
}

// Export singleton instance
export const historyLogger = new HistoryLogger();

